const fs=require('fs'),path=require('path');
const DATA_DIR=path.join(__dirname,'data');

const AUTHORS={
"汉乐府":"汉乐府是指由汉代朝廷音乐机关——乐府采集、整理的民间诗歌。乐府诗内容丰富，形式多样，语言朴素自然，反映了广泛的社会生活。",
"北朝民歌":"北朝民歌是指南北朝时期北方各民族的民间歌谣。风格粗犷豪放，气势雄浑，反映了北方民族的生活风貌和精神气质。",
"骆宾王":"骆宾王（约640—684），唐代文学家。与王勃、杨炯、卢照邻并称\"初唐四杰\"。七岁能文，尤长于七言歌行。著有《骆临海集》。",
"李峤":"李峤（644—714），唐代诗人。武则天至唐中宗时期宰相。工诗咏物，与崔融、苏味道、杜审言合称\"文章四友\"。",
"贺知章":"贺知章（659—744），唐代诗人、书法家。字季真，号四明狂客。性旷达，好饮酒。与李白友善。诗作清新通俗，著名的有《咏柳》《回乡偶书》等。",
"王之涣":"王之涣（688—742），唐代诗人。字季凌。其诗多被当时乐工制曲歌唱，以描写边塞风光著称。代表作有《登鹳雀楼》《凉州词》等。",
"孟浩然":"孟浩然（689—740），唐代诗人。襄州襄阳人。终生不仕，以隐居和漫游终其一生。与王维并称\"王孟\"，是盛唐山水田园诗派的代表。",
"王翰":"王翰，唐代诗人。生卒年不详。以边塞诗见长，性格豪放不羁。代表作《凉州词》被誉为唐代七绝压卷之作。",
"王昌龄":"王昌龄（约690—757），唐代诗人。字少伯。擅长七绝，被后人誉为\"七绝圣手\"。边塞诗气势雄浑，格调高昂。代表作有《出塞》《芙蓉楼送辛渐》等。",
"王维":"王维（701—761），唐代诗人、画家。字摩诘。苏轼评其\"诗中有画，画中有诗\"。晚年笃信佛教，隐居辋川。与孟浩然并称\"王孟\"，为盛唐山水田园诗派代表。",
"李白":"李白（701—762），唐代伟大的浪漫主义诗人。字太白，号青莲居士，有\"诗仙\"之称。其诗想象丰富，气势豪迈，语言清新自然。与杜甫并称\"李杜\"。代表作有《静夜思》《将进酒》《蜀道难》等。",
"杜甫":"杜甫（712—770），唐代伟大的现实主义诗人。字子美，自号少陵野老，有\"诗圣\"之称。其诗深刻反映社会现实，被称为\"诗史\"。代表作有\"三吏\"\"三别\"《春望》《登高》等。",
"柳宗元":"柳宗元（773—819），唐代文学家、哲学家。字子厚。与韩愈共同倡导古文运动，并称\"韩柳\"。为\"唐宋八大家\"之一。代表作有《江雪》《小石潭记》等。",
"贾岛":"贾岛（779—843），唐代诗人。字阆仙。曾为僧，法名无本。以苦吟著称，自谓\"二句三年得，一吟双泪流\"。与孟郊并称\"郊寒岛瘦\"。",
"张继":"张继，唐代诗人。生卒年不详。字懿孙。其诗多登临记行之作，代表作《枫桥夜泊》为千古传诵的名篇。",
"卢纶":"卢纶（约737—799），唐代诗人。字允言。\"大历十才子\"之一。以边塞诗著称，代表作有《塞下曲》等。",
"刘禹锡":"刘禹锡（772—842），唐代文学家、哲学家。字梦得。与白居易并称\"刘白\"。其诗通俗流畅，含蓄婉约。代表作有《竹枝词》《望洞庭》《秋词》等。",
"白居易":"白居易（772—846），唐代伟大的现实主义诗人。字乐天，号香山居士。倡导新乐府运动，主张\"文章合为时而著，歌诗合为事而作\"。代表作有《长恨歌》《琵琶行》《赋得古原草送别》等。",
"李绅":"李绅（772—846），唐代诗人。字公垂。与白居易、元稹交好，为新乐府运动倡导者之一。代表作有《悯农》二首。",
"杜牧":"杜牧（803—852），唐代诗人。字牧之。与李商隐并称\"小李杜\"。其诗英发俊爽，多伤时忧国之作。代表作有《泊秦淮》《山行》《清明》等。",
"李商隐":"李商隐（813—858），唐代诗人。字义山，号玉谿生。其诗构思新奇，风格秾丽，尤以爱情诗和咏史诗著称。代表作有《锦瑟》《无题》《夜雨寄北》等。",
"罗隐":"罗隐（833—909），晚唐诗人。字昭谏。其诗多讽刺时政之作，语言通俗。代表作有《蜂》等。",
"范仲淹":"范仲淹（989—1052），北宋政治家、文学家。字希文。政治上倡导改革，文学上以《岳阳楼记》著称。词作《渔家傲·秋思》开宋词豪放风气。",
"王安石":"王安石（1021—1086），北宋政治家、文学家、思想家。字介甫，号半山。\"唐宋八大家\"之一。推行王安石变法。代表作有《泊船瓜洲》《登飞来峰》《元日》等。",
"苏轼":"苏轼（1037—1101），北宋文学家、书画家。字子瞻，号东坡居士。\"唐宋八大家\"之一。其诗、词、文均成就极高。词开豪放一派，与辛弃疾并称\"苏辛\"。代表作有《水调歌头·明月几时有》《念奴娇·赤壁怀古》《题西林壁》等。",
"李清照":"李清照（1084—约1155），宋代女词人。号易安居士。婉约词派代表，有\"千古第一才女\"之称。前期词多写悠闲生活，后期多悲叹身世。代表作有《如梦令》《声声慢》《一剪梅》等。",
"陆游":"陆游（1125—1210），南宋诗人。字务观，号放翁。一生创作诗歌近万首，以爱国诗著称。与尤袤、杨万里、范成大并称\"南宋四大家\"。代表作有《示儿》《游山西村》等。",
"范成大":"范成大（1126—1193），南宋诗人。字致能，号石湖居士。与陆游、杨万里、尤袤并称\"南宋四大家\"。以田园诗著称。代表作有《四时田园杂兴》等。",
"朱熹":"朱熹（1130—1200），南宋理学家、文学家。字元晦，号考亭。集理学之大成，建立程朱理学体系。代表作有《春日》《观书有感》等。",
"林升":"林升，南宋诗人。生卒年不详。字梦屏。其《题临安邸》讽刺南宋统治者偏安苟且，是千古传诵的名篇。",
"叶绍翁":"叶绍翁，南宋诗人。字嗣宗，号靖逸。属江湖诗派。代表作有《游园不值》等。",
"翁卷":"翁卷，南宋诗人。字续古，号灵舒。\"永嘉四灵\"之一。诗作清新自然。代表作有《乡村四月》等。",
"王冕":"王冕（1287—1359），元代诗人、画家。字元章，号煮石山农。以画梅著称，诗多反映民间疾苦。代表作有《墨梅》等。",
"于谦":"于谦（1398—1457），明代政治家、诗人。字廷益。民族英雄，在\"土木堡之变\"后力挽狂澜。代表作有《石灰吟》等。",
"王勃":"王勃（650—676），唐代文学家。字子安。\"初唐四杰\"之首。代表作有《送杜少府之任蜀州》《滕王阁序》等。",
"岑参":"岑参（约715—770），唐代边塞诗人。与高适并称\"高岑\"。其边塞诗奇伟壮丽，代表作有《白雪歌送武判官归京》等。",
"曹操":"曹操（155—220），汉末政治家、军事家、文学家。字孟德。建安文学代表人物。其诗气魄宏大，慷慨悲凉。代表作有《观沧海》《短歌行》《龟虽寿》等。",
"陶渊明":"陶渊明（约365—427），东晋诗人。字元亮，号五柳先生。中国田园诗派鼻祖。其诗自然平淡，意境深远。代表作有《饮酒》《归园田居》《桃花源记》等。",
"韩愈":"韩愈（768—824），唐代文学家、思想家。字退之。\"唐宋八大家\"之首。倡导古文运动。代表作有《早春呈水部张十八员外》《师说》等。",
"温庭筠":"温庭筠（约812—866），晚唐诗人、词人。本名岐，字飞卿。花间词派鼻祖。词风秾丽，代表作有《菩萨蛮》《望江南》等。",
"李益":"李益（748—829），唐代诗人。字君虞。以边塞诗著称。代表作有《夜上受降城闻笛》等。",
"韦应物":"韦应物（737—792），唐代诗人。京兆万年人。其诗闲淡简雅，与王维、孟浩然、柳宗元并称\"王孟韦柳\"。代表作有《滁州西涧》等。",
"曾几":"曾几（1084—1166），南宋诗人。字吉甫。其诗风格清俊，陆游曾从其学诗。代表作有《三衢道中》等。",
"张若虚":"张若虚（约660—约720），唐代诗人。与贺知章等并称\"吴中四士\"。代表作《春江花月夜》被誉为\"孤篇盖全唐\"。",
"崔颢":"崔颢（约704—754），唐代诗人。其《黄鹤楼》被严羽评为唐人七律第一。",
"龚自珍":"龚自珍（1792—1841），清代思想家、文学家。字璱人，号定庵。近代改良主义先驱。代表作有《己亥杂诗》等。",
"王湾":"王湾，唐代诗人。生卒年不详。其《次北固山下》中\"海日生残夜，江春入旧年\"为名句，张九龄手书于政事堂。",
"诗经":"《诗经》是中国最早的诗歌总集，收录西周至春秋诗歌305篇，分风、雅、颂三类。反映当时社会生活各方面，开创中国现实主义诗歌传统。",
"古诗十九首":"《古诗十九首》是汉代文人五言诗的代表，作者不详。内容多写离愁别恨、人生感慨。刘勰评为\"五言之冠冕\"。",
"张志和":"张志和，唐代诗人、词人。字子同，号玄真子。其《渔歌子》为早期文人词中描写自然风光的名作。",
"李煜":"李煜（937—978），南唐后主。字重光。虽政治上亡国之君，但艺术才华卓越，尤以词著称。代表作有《虞美人》《浪淘沙令》等。",
"晏殊":"晏殊（991—1055），北宋词人。字同叔。其词风流蕴藉，温润秀洁。代表作有《浣溪沙》《蝶恋花》等。",
"柳永":"柳永（约984—约1053），北宋词人。原名三变，字景庄。大力创作慢词，发展了词的体制。代表作有《雨霖铃》《八声甘州》等。",
"辛弃疾":"辛弃疾（1140—1207），南宋词人。字幼安，号稼轩。豪放词派代表，与苏轼并称\"苏辛\"。词风慷慨悲壮，抒发爱国情怀。代表作有《破阵子》《永遇乐》《水龙吟》等。",
"秦观":"秦观（1049—1100），北宋词人。字少游，号淮海居士。\"苏门四学士\"之一。婉约词派代表。代表作有《鹊桥仙》《踏莎行》等。",
"姜夔":"姜夔（约1155—约1221），南宋词人、音乐家。字尧章，号白石道人。其词清空骚雅，代表作有《扬州慢》《暗香》等。",
"毛泽东":"毛泽东（1893—1976），伟大的马克思主义者，无产阶级革命家、战略家、理论家，中国共产党、中国人民解放军和中华人民共和国的主要缔造者和领导人。同时也是著名诗人、书法家。其诗词气势磅礴，意境深远。",
"秋瑾":"秋瑾（1875—1907），近代民主革命烈士。字璿卿，号竞雄。自称\"鉴湖女侠\"。其诗词慷慨激昂，抒发革命情怀。",
"纳兰性德":"纳兰性德（1655—1685），清代词人。原名成德，字容若。其词清新自然，哀婉缠绵。代表作有《浣溪沙》《长相思》等。",
"朱敦儒":"朱敦儒（1081—1159），南宋词人。字希真。其词多写隐逸生活，风格清旷。代表作有《相见欢》等。",
"李之仪":"李之仪（约1038—约1117），北宋词人。字端叔。其词清婉，代表作有《卜算子·我住长江头》等。"
};

const POEMS=[];
POEMS[1]={p:"jiāng nán kě cǎi lián，lián yè hé tián tián。\nyú xì lián yè jiān。yú xì lián yè dōng，yú xì lián yè xī，yú xì lián yè nán，yú xì lián yè běi。",t:"江南可以采莲，莲叶多么茂盛。鱼儿在莲叶间嬉戏。鱼儿在莲叶东边嬉戏，鱼儿在莲叶西边嬉戏，鱼儿在莲叶南边嬉戏，鱼儿在莲叶北边嬉戏。",k:[["可","可以、能够"],["田田","莲叶茂盛的样子"],["戏","嬉戏、玩耍"]],a:"这是一首采莲歌，反映了江南水乡采莲时的欢乐情景。全诗以莲叶为中心，以鱼儿的嬉戏为点缀，描绘了一幅生动活泼的江南采莲图。诗中东南西北四方连用，既展现了鱼儿欢快游动的场景，又体现了民歌反复咏唱的特色。"};
POEMS[2]={p:"qīng qīng yuán zhōng kuí，zhāo lù dài rì xī。\nyáng chūn bù dé zé，wàn wù shēng guāng huī。\ncháng kǒng qiū jié zhì，kūn huáng huá yè shuāi。\nbǎi chuān dōng dào hǎi，hé shí fù xī guī？\nshǎo zhuàng bù nǔ lì，lǎo dà tú shāng bēi。",t:"园中葵菜青青，朝露等待阳光晒干。春天的阳光布施恩泽，万物焕发光彩。常恐秋天到来，花叶枯黄衰败。百川东流到海，何时还能西归？少壮时不努力，老大时只能徒然悲伤。",k:[["晞","晒干"],["德泽","恩惠、恩泽"],["焜黄","颜色衰败的样子"],["徒","白白地、徒然"]],a:"这是一首劝勉诗，以园中葵菜为喻，说明万物盛衰有时。前四句写春日万物生机勃勃，中四句转写秋来花叶凋零，后四句以百川东流不复西归为喻，劝人珍惜少壮时光。\"少壮不努力，老大徒伤悲\"为千古名句，告诫人们要珍惜光阴，及时努力。"};
POEMS[3]={p:"chì lè chuān，yīn shān xià。\ntiān sì qióng lú，lǒng gài sì yě。\ntiān cāng cāng，yě máng máng，\nfēng chuī cǎo dī jiàn niú yáng。",t:"敕勒川，阴山脚下。天空像圆顶毡帐，笼罩着四方原野。天苍苍，野茫茫，风吹低了牧草，露出了牛羊。",k:[["穹庐","游牧民族住的圆顶毡帐"],["笼盖","笼罩"],["苍苍","深青色"]],a:"这是一首北朝民歌，描绘了北方草原壮阔雄浑的自然风光。前三句写天地之大，以\"穹庐\"为喻，形象地表现了草原天空的形状。末句\"风吹草低见牛羊\"最为精彩，风吹草低之际，牛羊时隐时现，为静穆的画面增添了动感和生机。全诗境界开阔，气势磅礴，体现了北方民族的豪迈气质。"};
POEMS[4]={p:"é，é，é，\nqū xiàng xiàng tiān gē。\nbái máo fú lǜ shuǐ，\nhóng zhǎng bō qīng bō。",t:"鹅，鹅，鹅，弯着脖子向天唱歌。白毛浮在绿水上，红掌拨动着清波。",k:[["曲项","弯着脖子"],["拨","拨动"]],a:"相传为骆宾王七岁时所作。全诗以儿童的眼光观察白鹅，色彩鲜明（白毛、绿水、红掌、清波），动静结合（浮、拨），生动地描绘了鹅在水中游弋的形态。三个\"鹅\"字连用，既模拟了鹅的叫声，又表现了儿童的惊喜之情。"};
POEMS[5]={p:"jiě luò sān qiū yè，néng kāi èr yuè huā。\nguò jiāng qiān chǐ làng，rù zhú wàn gān xié。",t:"能吹落三秋的树叶，能吹开二月的春花。刮过江面能卷起千尺巨浪，吹入竹林能使万竿竹子倾斜。",k:[["解","能够、懂得"],["三秋","深秋，秋季三个月"],["斜","倾斜"]],a:"这是一首咏物诗，全诗无一\"风\"字，却句句写风。通过风吹落秋叶、吹开春花、卷起巨浪、吹斜竹林四个场景，从不同角度展现了风的力量。对仗工整，数字巧妙（三、二、千、万），是咏物诗中的佳作。"};
POEMS[6]={p:"bì yù zhuāng chéng yī shù gāo，wàn tiáo chuí xià lǜ sī tāo。\nbù zhī xì yè shuí cái chū，èr yuè chūn fēng sì jiǎn dāo。",t:"碧玉妆扮成一棵高树，万条垂下绿色的丝带。不知细叶是谁裁剪出来的，二月的春风好似剪刀。",k:[["碧玉","绿色美玉，喻柳树"],["妆成","装饰成"],["绦","丝带"]],a:"这是一首咏物诗，以丰富的想象和巧妙的比喻描绘了早春杨柳的嫩绿轻柔。首句以\"碧玉\"喻柳树，写出其颜色之美；次句以\"丝绦\"喻柳条，写出其形态之柔。后两句以问句形式，将春风比作剪刀，构思新颖，化静为动，赞美了春风创造万物的力量。"};
POEMS[7]={p:"shǎo xiǎo lí jiā lǎo dà huí，xiāng yīn wú gǎi bìn máo cuī。\nér tóng xiāng jiàn bù xiāng shí，xiào wèn kè cóng hé chù lái。",t:"年少时离开家乡，年老才回来。乡音没有改变，鬓发却已稀疏。儿童相见却不认识，笑着问客人从哪里来。",k:[["少小","年少"],["老大","年老"],["衰","疏落、稀疏"]],a:"这是贺知章晚年辞官回乡时所作。全诗在平淡的叙述中蕴含着深沉的感慨。前两句写离家与归来的时间跨度之大，乡音未改而鬓毛已衰，物是人非。后两句以儿童的不识与笑问，反衬出自己的老迈和久客伤老之情。全诗语言朴实，情感真挚，是回乡诗中的名篇。"};
POEMS[8]={p:"huáng hé yuǎn shàng bái yún jiān，yī piàn gū chéng wàn rèn shān。\nqiāng dí hé xū yuàn yáng liǔ，chūn fēng bù dù yù mén guān。",t:"黄河远远直上白云之间，一片孤城矗立在万仞高山中。羌笛何须怨杨柳不发芽，春风吹不到玉门关。",k:[["仞","古代长度单位，八尺为一仞"],["羌笛","古代羌族乐器"],["度","越过、吹到"]],a:"这是一首边塞诗，描绘了边塞的荒凉和戍边将士的思乡之情。首句以黄河、白云写边塞的壮阔，次句以孤城写戍地的荒凉。后两句以羌笛怨杨柳，实写戍边将士的思乡之情，而\"春风不度玉门关\"既是写实，也暗喻朝廷不关心边塞将士。全诗悲而不哀，怨而不怒，格调雄浑。"};
POEMS[9]={p:"bái rì yī shān jìn，huáng hé rù hǎi liú。\nyù qióng qiān lǐ mù，gèng shàng yī céng lóu。",t:"白日依傍着山峦落下去，黄河奔腾着流入大海。想要看到千里之外的景色，就要再登上一层楼。",k:[["依","依傍、靠着"],["尽","消失"],["穷","尽、看尽"]],a:"这是一首登高望远之作。前两句写登楼所见的壮阔景象：落日、黄河、山、海，气势磅礴。后两句由景入理，含蓄地表达了积极向上的进取精神和高瞻远瞩的胸襟。全诗只有二十个字，却气象万千，意蕴深远，是千古传诵的名篇。"};
POEMS[10]={p:"chūn mián bù jué xiǎo，chù chù wén tí niǎo。\nyè lái fēng yǔ shēng，huā luò zhī duō shǎo。",t:"春天睡眠不知不觉就到了天亮，到处听到鸟儿的鸣叫。夜里传来风雨之声，不知落了多少花瓣。",k:[["晓","天亮、早晨"],["闻","听到"]],a:"这是一首描写春晨的诗。首句写春眠的香甜，次句写鸟鸣的悦耳，第三句回忆夜来风雨，末句关切花落多少。全诗不直接写春景之美，而是通过诗人的感受和心理活动来表现。语言平易自然，意境含蓄优美，体现了孟浩然诗\"淡而有味\"的特色。"};
POEMS[11]={p:"pú táo měi jiǔ yè guāng bēi，yù yǐn pí pá mǎ shàng cuī。\nzuì wò shā chǎng jūn mò xiào，gǔ lái zhēng zhàn jǐ rén huí？",t:"葡萄美酒斟满夜光杯，正要饮酒时琵琶声马上催促。醉倒在沙场上请你不要笑，自古以来征战有几人能回？",k:[["夜光杯","用白玉制成的酒杯，夜间发光"],["沙场","战场"]],a:"这是一首边塞诗，描写了边塞将士饮酒宴乐的场面。首句写酒美器精，次句写琵琶催饮，三句写醉卧沙场的豪迈，末句以反问作结，道出将士们视死如归的气概。全诗豪放悲壮，\"醉卧沙场君莫笑\"一句尤为传神，既有旷达豪放之气，又含悲凉感慨之情。"};
POEMS[12]={p:"qín shí míng yuè hàn shí guān，wàn lǐ cháng zhēng rén wèi huán。\ndàn shǐ lóng chéng fēi jiàng zài，bù jiào hú mǎ dù yīn shān。",t:"秦时的明月汉时的边关，万里长征的将士还未生还。只要龙城飞将还在，就不让胡人的战马越过阴山。",k:[["但使","只要"],["龙城飞将","指汉代名将李广，匈奴称其为\"飞将军\""],["度","越过"]],a:"这是一首著名的边塞诗。首句\"秦时明月汉时关\"以互文手法，将明月和边关置于秦汉的历史背景下，写出边塞的古老和战争的绵延。次句写将士久戍未归的悲哀。后两句表达了对良将的渴望和保家卫国的决心。全诗意境开阔，格调悲壮，被誉为唐人七绝的压卷之作。"};
POEMS[13]={p:"hán yǔ lián jiāng yè rù wú，píng míng sòng kè chǔ shān gū。\nluò yáng qīn yǒu rú xiāng wèn，yī piàn bīng xīn zài yù hú。",t:"寒雨连夜润湿了吴地，清晨送客面对楚山的孤影。洛阳亲友如果问起我，就说我的心像玉壶中的冰一样纯洁。",k:[["平明","清晨"],["冰心","像冰一样晶莹纯洁的心"],["玉壶","玉制的壶，比喻高洁"]],a:"这是一首送别诗。前两句写送别的环境：寒雨、孤山，渲染了凄凉的氛围。后两句以\"冰心玉壶\"自喻，表达了自己虽遭贬谪却依然保持高洁品格的决心。\"一片冰心在玉壶\"是千古名句，后来成为清廉高洁的象征。"};
POEMS[14]={p:"kōng shān bù jiàn rén，dàn wén rén yǔ xiǎng。\nfǎn yǐng rù shēn lín，fù zhào qīng tái shàng。",t:"空山中看不见人影，只听到人说话的回声。夕阳的返照映入深林，又照在青苔上面。",k:[["但","只、仅"],["返景","夕阳返照。景，同\"影\""],["复","又"]],a:"这是一首山水诗，描绘了鹿柴傍晚时分的幽静景色。首句\"空山不见人\"写山的空寂，次句\"但闻人语响\"以声衬静，三、四句以夕阳余晖照在青苔上的细微景象，进一步渲染了幽寂的氛围。全诗以动衬静，以声衬寂，体现了王维\"诗中有画\"的特色和禅意。"};
POEMS[15]={p:"wèi chéng zhāo yǔ yì qīng chén，kè shè qīng qīng liǔ sè xīn。\nquàn jūn gèng jìn yī bēi jiǔ，xī chū yáng guān wú gù rén。",t:"渭城早晨的雨润湿了轻尘，客舍旁柳色青翠一新。劝你再喝一杯酒，向西出了阳关就没有老朋友了。",k:[["浥","润湿"],["客舍","旅店"],["阳关","古关名，在今甘肃敦煌西南"]],a:"这是一首送别诗，又名《渭城曲》。前两句写送别的时间、地点和环境，雨后柳色清新，点明春天。后两句写惜别之情，\"更尽一杯酒\"以酒寄情，\"西出阳关无故人\"道出前路孤寂的感慨。全诗语浅情深，后来被谱为《阳关三叠》传唱。"};
POEMS[16]={p:"dú zài yì xiāng wéi yì kè，měi féng jiā jié bèi sī qīn。\nyáo zhī xiōng dì dēng gāo chù，biàn chā zhū yú shǎo yī rén。",t:"独自在异乡做异客，每逢佳节就加倍思念亲人。遥想兄弟们登高的地方，插遍茱萸只少了我一个人。",k:[["异乡","他乡"],["登高","重阳节登高的习俗"],["茱萸","一种香草，重阳节佩以辟邪"]],a:"这是一首思乡怀亲之作。首句写客居异乡的孤独，次句写佳节思亲的深情。后两句从对面落笔，不写自己思亲，而写兄弟们登高时发现少了一人，从而反衬出自己的思乡之情。这种\"对面落笔\"的手法使感情更加深沉含蓄。全诗质朴自然，情真意切。"};
POEMS[17]={p:"chuáng qián míng yuè guāng，yí shì dì shàng shuāng。\njǔ tóu wàng míng yuè，dī tóu sī gù xiāng。",t:"床前洒满明月的光辉，疑是地上结了一层白霜。抬起头望着明月，低下头思念故乡。",k:[["疑","怀疑、以为"],["举","抬起"]],a:"这是一首脍炙人口的思乡诗。首句写月色如霜，次句以\"疑\"字写出似睡非睡的恍惚之感。后两句\"举头\"\"低头\"两个动作，将望月与思乡自然衔接。全诗仅二十个字，却将月夜思乡之情表达得淋漓尽致，语言明白如话，意境深远，是千古传诵的名篇。"};
POEMS[18]={p:"xiǎo shí bù shí yuè，hū zuò bái yù pán。\nyòu yí yáo tái jìng，fēi zài qīng yún duān。",t:"小时候不认识月亮，把它叫做白玉盘。又怀疑是瑶台的仙镜，飞在青云之端。",k:[["呼作","叫做、称为"],["瑶台","传说中神仙居住的地方"]],a:"这是《古朗月行》的前四句，以儿童的口吻描写月亮。诗人回忆幼时不识月，将月亮比作\"白玉盘\"和\"瑶台镜\"，充满了童趣和想象。语言清新活泼，比喻生动形象，展现了李白诗歌浪漫主义的艺术特色。"};
POEMS[19]={p:"rì zhào xiāng lú shēng zǐ yān，yáo kàn pù bù guà qián chuān。\nfēi liú zhí xià sān qiān chǐ，yí shì yín hé luò jiǔ tiān。",t:"阳光照射香炉峰升起紫烟，远看瀑布像白练挂在山前。飞流直下有三千尺长，疑是银河从九天落下。",k:[["香炉","庐山香炉峰"],["前川","山前"],["银河","天河"]],a:"这是一首描写庐山瀑布的山水诗。首句写香炉峰在阳光照射下云雾升腾如紫烟，次句写远望瀑布如白练高挂。后两句\"飞流直下三千尺\"写瀑布的气势，\"疑是银河落九天\"以奇特的想象将瀑布比作天河坠落。全诗夸张奇特，想象丰富，体现了李白诗歌豪放飘逸的风格。"};
POEMS[20]={p:"lǐ bái chéng zhōu jiāng yù xíng，hū wén àn shàng tà gē shēng。\ntáo huā tán shuǐ shēn qiān chǐ，bù jí wāng lún sòng wǒ qíng。",t:"李白乘船将要出发，忽然听到岸上传来踏歌之声。桃花潭水有千尺深，也比不上汪伦送我的情意深。",k:[["将欲","将要"],["踏歌","唱歌时以足踏地为节拍"],["不及","不如、比不上"]],a:"这是一首赠别诗。前两句叙事，写乘舟将行时忽闻歌声。后两句以桃花潭水之深比喻汪伦送别之情的深厚，\"不及\"二字将无形的情谊与有形的潭水相比较，化抽象为具体。全诗自然真率，不假雕饰，体现了李白重情谊的性格。"};
POEMS[21]={p:"gù rén xī cí huáng hè lóu，yān huā sān yuè xià yáng zhōu。\ngū fān yuǎn yǐng bì kōng jìn，wéi jiàn cháng jiāng tiān jì liú。",t:"老朋友辞别黄鹤楼东去，在烟花如雾的三月下扬州。孤帆的远影消失在碧空尽头，只看见长江水天际流去。",k:[["辞","辞别、告别"],["烟花","形容春景如烟如雾"],["唯","只"]],a:"这是一首送别诗的名篇。首句点明送别地点，次句写明去往之处和时间，\"烟花三月\"四字写尽春日扬州之美。后两句写目送帆影远去，直到帆影消失在碧空尽头，只见长江天际流，以景结情，将惜别之情寓于无尽的江流之中。全诗意境开阔，风流潇洒。"};
POEMS[22]={p:"zhāo cí bái dì cǎi yún jiān，qiān lǐ jiāng líng yī rì huán。\nliǎng àn yuán shēng tí bù zhù，qīng zhōu yǐ guò wàn chóng shān。",t:"清晨告别白帝城在彩云之间，千里江陵一天就返回。两岸猿声啼叫不停，轻舟已经穿过万重山。",k:[["辞","告别"],["江陵","今湖北江陵"],["万重山","层层叠叠的山"]],a:"这是李白流放途中遇赦后所作。首句写白帝城高在彩云间，次句写江行迅速，\"千里\"\"一日\"对比鲜明。后两句以猿声的哀啼反衬舟行的轻快，\"啼不住\"与\"已过\"相呼应，将遇赦后的喜悦之情表达得淋漓尽致。全诗气势奔放，轻快流畅。"};
POEMS[23]={p:"tiān mén zhōng duàn chǔ jiāng kāi，bì shuǐ dōng liú zhì cǐ huí。\nliǎng àn qīng shān xiāng duì chū，gū fān yī piàn rì biān lái。",t:"天门山中间断开楚江通过，碧水东流到这里回旋。两岸青山相对耸立，一片孤帆从日边驶来。",k:[["中断","从中间断开"],["至此回","到这里回旋"],["日边","太阳旁边，喻指远方"]],a:"这是一首描写天门山的山水诗。首句写天门山夹江对峙的雄伟气势，次句写江水至天门山处回旋的壮观。后两句写青山相对、孤帆远来的画面。全诗将大景与小景、远景与近景结合，画面壮阔，色彩鲜明，体现了李白诗歌豪放的风格。"};
POEMS[24]={p:"liǎng gè huáng lí míng cuì liǔ，yī xíng bái lù shàng qīng tiān。\nchuāng hán xī lǐng qiān qiū xuě，mén pō dōng wú wàn lǐ chuán。",t:"两只黄鹂在翠柳间鸣叫，一行白鹭飞上青天。窗户含着西岭千秋的雪，门前停泊着东吴万里的船。",k:[["含","包含、镶嵌"],["泊","停泊"],["东吴","今江苏浙江一带"]],a:"这是杜甫成都草堂所作。全诗四句四景：黄鹂翠柳（近景）、白鹭青天（远景）、西岭雪窗（仰视）、东吴船门（俯视）。色彩鲜明（黄、翠、白、青），对仗工整，由近及远，由小到大，展现了一幅明媚开阔的春日画面。体现了杜甫\"诗中有画\"的艺术特色。"};
POEMS[25]={p:"hǎo yǔ zhī shí jié，dāng chūn nǎi fā shēng。\nsuí fēng qián rù yè，rùn wù xì wú shēng。\nyě jìng yún jù hēi，jiāng chuán huǒ dú míng。\nxiǎo kàn hóng shī chù，huā zhòng jǐn guān chéng。",t:"好雨知道下雨的时节，在春天植物萌发时就下起来了。随着春风在夜里悄悄下，润物细密无声。野径上乌云俱黑，江船上灯火独明。早晨看红湿之处，花重锦官城。",k:[["知时节","知道下雨的节气时节"],["潜","悄悄地、暗暗地"],["润物","滋润万物"],["花重","花因沾雨水而沉重"]],a:"这是杜甫寓居成都时所作。首联赞美春雨知时节，颔联写春雨润物无声的特点，颈联写雨夜景象，尾联想象雨后花团锦簇的美景。全诗围绕\"喜\"字展开，不直接写喜，而通过描写雨的特征和雨后景象来表现。\"润物细无声\"为千古名句，常用来赞美潜移默化的教育。"};
POEMS[26]={p:"qiān shān niǎo fēi jué，wàn jìng rén zōng miè。\ngū zhōu suō lì wēng，dú diào hán jiāng xuě。",t:"千山万岭不见飞鸟的踪影，万径千路不见行人的足迹。江面孤舟上一位披蓑戴笠的老翁，独自在寒江的雪中垂钓。",k:[["绝","断绝、消失"],["灭","消失、没有"],["蓑笠","蓑衣和斗笠，雨雪天穿的"]],a:"这是一首描写雪景的山水诗。前两句以\"千山\"\"万径\"极写天地之大，又以\"鸟飞绝\"\"人踪灭\"写万物空寂，营造出大雪封山的空旷冷寂氛围。后两句聚焦于孤舟蓑笠翁独钓寒江，以大景衬托小景，以动衬静。全诗寄托了诗人被贬永州后孤高傲岸的品格。"};
POEMS[27]={p:"sōng xià wèn tóng zǐ，yán shī cǎi yào qù。\nzhǐ zài cǐ shān zhōng，yún shēn bù zhī chù。",t:"松树下询问童子，他说师父采药去了。只在这座山中，云雾深浓不知在何处。",k:[["童子","指隐者的弟子、书童"],["言","说"],["处","地方、所在"]],a:"这是一首寻访隐者不遇的诗。全诗以问答形式展开：问童子师父何在，答曰采药去了；追问去何处采药，答曰就在此山中；再问山中何处，答曰云深不知处。层层递进，将不遇的怅惘转化为对隐者生活的想象。\"云深不知处\"意境幽远，既写山中云雾，又暗喻隐者的高洁飘逸。"};
POEMS[28]={p:"yuè luò wū tí shuāng mǎn tiān，jiāng fēng yú huǒ duì chóu mián。\ngū sū chéng wài hán shān sì，yè bàn zhōng shēng dào kè chuán。",t:"月亮落下乌鸦啼叫霜满天，江边枫树渔火对着我愁眠。姑苏城外寒山寺，半夜钟声传到客船。",k:[["愁眠","因愁而难以入睡"],["姑苏","苏州的别称"]],a:"这是一首旅途夜泊的诗。首句写月落、乌啼、霜满天，营造凄清氛围。次句写江枫渔火对愁眠，将景物与心情融合。后两句写寒山寺夜半钟声传到客船，以声衬静，将旅人的愁绪推向深处。全诗将落月、啼乌、满天霜、江枫、渔火、寒山寺、夜半钟声等意象组合，意境深远，是千古传诵的名篇。"};
POEMS[29]={p:"yuè hēi yàn fēi gāo，dān yú yè dùn táo。\nyù jiāng qīng qí zhú，dà xuě mǎn gōng dāo。",t:"月黑之夜大雁飞得高高，单于趁夜遁逃。正要率轻骑追击，大雪落满了弓刀。",k:[["单于","匈奴首领的称号"],["遁逃","逃跑"],["轻骑","轻装快速的骑兵"]],a:"这是一首边塞诗，描写了将士雪夜追击敌军的场景。首句\"月黑雁飞高\"写边塞夜景，次句\"单于夜遁逃\"写敌军败逃。后两句\"欲将轻骑逐\"写将士准备追击，\"大雪满弓刀\"写天寒地冻、大雪纷飞的艰苦环境。全诗气势雄壮，展现了将士们英勇无畏的精神。"};
POEMS[30]={p:"hú guāng qiū yuè liǎng xiāng hé，tán miàn wú fēng jìng wèi mó。\nyáo wàng dòng tíng shān shuǐ cuì，bái yín pán lǐ yī qīng luó。",t:"湖光秋月两相和谐，潭面无风像未打磨的铜镜。遥望洞庭山水翠绿，白银盘里放着一只青螺。",k:[["和","和谐、协调"],["未磨","未经打磨，指铜镜"],["白银盘","喻洞庭湖"],["青螺","喻君山"]],a:"这是一首描写洞庭湖秋色的山水诗。首句写湖光与秋月交辉，次句以未磨铜镜喻湖面平静。后两句以白银盘喻洞庭湖、青螺喻君山，想象奇特，比喻精巧。全诗色彩明丽（翠、白、青），将大景写得小巧玲珑，体现了诗人丰富的想象力和高超的艺术技巧。"};
POEMS[31]={p:"lí lí yuán shàng cǎo，yī suì yī kū róng。\nyě huǒ shāo bù jìn，chūn fēng chuī yòu shēng。\nyuǎn fāng qīn gǔ dào，qíng cuì jiē huāng chéng。\nyòu sòng wáng sūn qù，qī qī mǎn bié qíng。",t:"原野上长满茂盛的草，一年一度枯萎又繁茂。野火烧不尽它，春风吹过又生发出来。远处的芳草侵占了古道，晴天的翠绿连接着荒城。又送别王孙离去，茂盛的草满含离别之情。",k:[["离离","草木茂盛的样子"],["一岁","一年"],["枯荣","枯萎和繁茂"],["王孙","贵族子弟，此指被送别的人"]],a:"这是白居易十六岁时应考的习作。全诗借咏春草抒写送别之情。\"野火烧不尽，春风吹又生\"为千古名句，以野火之烈反衬春草生命力之顽强，蕴含哲理。后四句将春草与离别结合，以草的蔓延喻别情的绵长。全诗借物抒情，情景交融，是咏物送别诗中的佳作。"};
POEMS[32]={p:"xiǎo wá chēng xiǎo tǐng，tōu cǎi bái lián huí。\nbù jiě cáng zōng jì，fú píng yī dào kāi。",t:"小娃撑着小船，偷采了白莲回来。不懂得隐藏踪迹，浮萍被船荡开一道开路。",k:[["小娃","小孩"],["艇","小船"],["踪迹","痕迹、踪印"]],a:"这是一首描写儿童生活的小诗。前两句叙事，写小娃偷采白莲的顽皮可爱。后两句写他不懂得隐藏，船过浮萍开，留下了明显的痕迹。全诗充满生活情趣，以白描手法刻画了天真烂漫的儿童形象，语言通俗浅显，风格清新活泼。"};
POEMS[33]={p:"chú hé rì dāng wǔ，hàn dī hé xià tǔ。\nshuí zhī pán zhōng cān，lì lì jiē xīn kǔ。",t:"锄禾在烈日当空的正午，汗水滴入禾苗下的泥土。谁知盘中的饭食，粒粒都是辛苦换来的。",k:[["锄禾","给禾苗锄草"],["当午","正午时分"],["餐","饭食"]],a:"这是一首悯农诗，告诫人们珍惜粮食。前两句描写农民正午烈日下锄草的辛劳，汗滴入土。后两句以反问发出感慨，将盘中餐与农民辛苦联系起来。\"谁知盘中餐，粒粒皆辛苦\"为千古名句，语言通俗而道理深刻，是劝勉人们珍惜劳动成果的名篇。"};
POEMS[34]={p:"chūn zhòng yī lì sù，qiū shōu wàn kē zǐ。\nsì hǎi wú xián tián，nóng fū yóu è sǐ。",t:"春天种下一粒种子，秋天收获万颗子。四海之内没有闲田，农民还是饿死了。",k:[["一粒粟","一粒谷种"],["万颗子","万颗谷粒"],["犹","还是、仍然"]],a:"这是一首悯农诗，揭露了社会的不公。前两句写春种秋收的丰收景象，\"一粒\"与\"万颗\"对比鲜明。后两句以\"无闲田\"的丰收与\"犹饿死\"的悲剧形成强烈反差，深刻揭露了封建社会中农民辛勤劳动却仍不免饿死的残酷现实。全诗字字血泪，饱含对农民的深切同情。"};
POEMS[35]={p:"yuǎn shàng hán shān shí jìng xié，bái yún shēng chù yǒu rén jiā。\ntíng chē zuò ài fēng lín wǎn，shuāng yè hóng yú èr yuè huā。",t:"远远的寒山石径歪斜，白云生处有人家。停下车来是因为爱枫林晚景，霜染的枫叶比二月的花还红。",k:[["斜","歪斜、弯曲"],["坐","因为"],["霜叶","经霜变红的枫叶"]],a:"这是一首描写秋山红叶的山水诗。首句写山高路远，次句写白云深处有人家，展现深山意境。后两句写停车赏枫，\"霜叶红于二月花\"是千古名句，以春花喻秋叶，打破了悲秋的传统格调，赋予秋天以生机勃勃的春意，体现了诗人豪迈开朗的性情。"};
POEMS[36]={p:"qīng míng shí jié yǔ fēn fēn，lù shàng xíng rén yù duàn hún。\njiè wèn jiǔ jiā hé chù yǒu，mù tóng yáo zhǐ xìng huā cūn。",t:"清明时节细雨纷纷，路上行人魂魄欲断。借问酒家何处有，牧童遥指杏花村。",k:[["断魂","形容神情凄迷、愁苦"],["遥指","远远地指着"]],a:"这是一首描写清明时节旅人愁绪的诗。首句写清明雨景，次句写行人愁苦。后两句以问答形式写寻酒避雨，\"遥指杏花村\"以景结情，余味无穷。全诗语言通俗，意境清新，将清明时节的凄迷氛围与旅人的愁绪巧妙融合，是清明诗中的千古名篇。"};
POEMS[37]={p:"qiān lǐ yīng tí lǜ yìng hóng，shuǐ cūn shān guō jiǔ qí fēng。\nnán cháo sì bǎi bā shí sì，duō shǎo lóu tái yān yǔ zhōng。",t:"千里莺啼绿映红，水村山郭酒旗迎风。南朝四百八十寺，多少楼台掩映在烟雨中。",k:[["郭","外城，此指城"],["酒旗","酒家的布招牌"],["四百八十寺","南朝佛寺极多，此为约数"]],a:"这是一首描写江南春景的诗。前两句写江南春色：莺啼、绿红、水村、山郭、酒旗，展现了一幅明丽广阔的江南春景图。后两句转入怀古，以南朝佛寺在烟雨中的朦胧景象，暗含对历史兴亡的感慨。全诗将写景与怀古结合，意境深远，既有春景之美，又有历史之思。"};
POEMS[38]={p:"yān lóng hán shuǐ yuè lóng shā，yè pō qín huái jìn jiǔ jiā。\nshāng nǚ bù zhī wáng guó hèn，gé jiāng yóu chàng hòu tíng huā。",t:"烟雾笼罩寒水月色笼罩沙岸，夜泊秦淮靠近酒家。歌女不知亡国之恨，隔江还在唱着后庭花。",k:[["笼","笼罩"],["秦淮","秦淮河，在南京"],["商女","歌女"],["后庭花","陈后主所作亡国之音"]],a:"这是一首咏史怀古诗。前两句写夜泊秦淮的景色，烟水朦胧。后两句借歌女唱后庭花发感慨，表面责歌女不知亡国之恨，实则讽刺晚唐统治者沉溺声色、不吸取历史教训。全诗含蓄深沉，将写景、叙事、议论融为一体，体现了杜牧咏史诗的特色。"};
POEMS[39]={p:"xiàng wǎn yì bù shì，qū chē dēng gǔ yuán。\nxī yáng wú xiàn hǎo，zhǐ shì jìn huáng hūn。",t:"傍晚时心情不适，驾车登上古原。夕阳无限美好，只是已近黄昏。",k:[["向晚","傍晚"],["意不适","心情不舒畅"],["古原","乐游原，长安郊外胜地"]],a:"这是一首登高览景的诗。首句写傍晚心情郁闷，次句写驱车登古原散心。后两句\"夕阳无限好，只是近黄昏\"是千古名句，既写夕阳之美与短暂，又隐喻好景不长、迟暮将至的感慨。全诗将写景与抒情完美结合，既有对自然美景的赞叹，又有对人生迟暮的感伤，意境深远。"};
POEMS[40]={p:"bù lùn píng dì yǔ shān jiān，wú xiàn fēng guāng jìn bèi zhàn。\ncǎi dé bǎi huā chéng mì hòu，wèi shuí xīn kǔ wèi shuí tián。",t:"不论平地还是山尖，无限风光都被占尽。采得百花酿成蜜后，为谁辛苦为谁甜？",k:[["占","占据、占有"],["为","为了"]],a:"这是一首咏物诗，以蜜蜂为描写对象。前两句写蜜蜂占尽平地山尖的风光，采遍百花。后两句以反问作结，\"为谁辛苦为谁甜\"既是对蜜蜂的同情，也是对人类社会不公的暗讽。全诗借物喻人，寓意深远，既可以理解为对劳动者的同情，也可以看作对追逐名利者的讽喻。"};
POEMS[41]={p:"jiāng shàng wǎng lái rén，dàn ài lú yú měi。\njūn kàn yī yè zhōu，chū mò fēng bō lǐ。",t:"江上来来往往的人，只爱鲈鱼的美味。请看那一叶小舟，在风浪中出没。",k:[["但","只、仅"],["一叶舟","像一片叶子似的小船"],["出没","时隐时现"]],a:"这是一首反映渔民辛劳的诗。前两句写江上行人只知品尝鲈鱼之美，后两句以\"君看\"呼吁关注渔民在风浪中打鱼的艰辛。全诗通过对比食鱼者与打鱼者，表达了对渔民深切的同情。语言朴素，对比鲜明，与《悯农》异曲同工。"};
POEMS[42]={p:"bào zhú shēng zhōng yī suì chú，chūn fēng sòng nuǎn rù tú sū。\nqiān mén wàn hù tóng tóng rì，zǒng bǎ xīn táo huàn jiù fú。",t:"爆竹声中一年过去，春风送暖入屠苏酒。千门万户沐浴着朝阳，总把新桃换下旧符。",k:[["除","过去、逝去"],["屠苏","屠苏酒，春节饮以避邪"],["曈曈日","朝阳灿烂的样子"],["桃","桃符，春联"]],a:"这是一首描写春节的诗。首句写爆竹声中旧岁已除，次句写春风送暖饮屠苏酒。后两句写千家万户在朝阳中换新桃符，\"总把新桃换旧符\"暗含诗人推行新法的政治抱负。全诗洋溢着春节的喜庆气氛，格调明快，充满除旧布新的积极精神。"};
POEMS[43]={p:"jīng kǒu guā zhōu yī shuǐ jiān，zhōng shān zhǐ gé shù chóng shān。\nchūn fēng yòu lǜ jiāng nán àn，míng yuè hé shí zhào wǒ huán。",t:"京口和瓜洲一水之隔，钟山只隔着几重山。春风又吹绿了江南岸，明月什么时候照着我回来？",k:[["一水间","被一条水隔开"],["数重山","几层山"],["绿","吹绿、变绿"]],a:"这是一首思乡诗。前两句写泊船瓜洲时所见，由近及远写京口、钟山。后两句\"春风又绿江南岸\"写春景，\"明月何时照我还\"写思归之情。\"绿\"字传神，将春风拟人化，赋予其动态。全诗以景起情，借春风明月抒发思乡之愁，语言清丽，感情真挚。"};
POEMS[44]={p:"máo yán cháng sǎo jìng wú tái，huā mù chéng qí shǒu zì zāi。\nyī shuǐ hù tián jiāng lǜ rào，liǎng shān pái tà sòng qīng lái。",t:"茅檐常扫干净无青苔，花木成畦亲手栽种。一水护田将绿环绕，两山推门送青来。",k:[["畦","田亩分区"],["排闼","推门"],["闼","门"]],a:"这是一首描写田园风光的诗。前两句写庭院整洁、花木成行，是近景。后两句写一水护田、两山送青，是远景。\"排闼送青\"将山拟人化，仿佛青山推门而入送来绿色，构思新颖。全诗将静态景物写得生动活泼，体现了王安石写景诗的功力。"};
POEMS[45]={p:"hēi yún fān mò wèi zhē shān，bái yǔ tiào zhū luàn rù chuán。\njuǎn dì fēng lái hū chuī sàn，wàng hú lóu xià shuǐ rú tiān。",t:"黑云翻墨未遮住山，白雨跳珠乱入船。卷地风来忽然吹散，望湖楼下水如天。",k:[["翻墨","打翻墨汁，喻乌云"],["跳珠","跳动的珍珠，喻雨点"],["卷地风","席卷而来的风"]],a:"这是苏轼在杭州所作的写景诗。前两句写暴雨骤来：乌云如翻墨、白雨如跳珠，比喻生动。后两句写风来雨散，水天一色。全诗以\"未遮山\"\"乱入船\"\"忽吹散\"等词语，生动地表现了夏日阵雨来去匆匆的特点。画面变幻快速，色彩鲜明，体现了苏轼诗歌的豪放风格。"};
POEMS[46]={p:"shuǐ guāng liàn yàn qíng fāng hǎo，shān sè kōng méng yǔ yì qí。\nyù bǎ xī hú bǐ xī zǐ，dàn zhuāng nóng mǒ zǒng xiāng yí。",t:"水光潋滟晴天正好，山色空蒙雨天也奇。想把西湖比作西施，淡妆浓抹总相宜。",k:[["潋滟","水波荡漾的样子"],["空蒙","雾气迷茫的样子"],["西子","西施，古代美女"],["相宜","合适"]],a:"这是一首赞美西湖的诗。前两句分写晴雨两种天气的西湖之美，后两句以美人西施喻西湖，\"淡妆浓抹总相宜\"将晴雨西湖之美概括为浓淡皆宜。全诗比喻精妙，将西湖人格化，是咏西湖诗中的千古绝唱。\"欲把西湖比西子\"也成为西湖的代名词。"};
POEMS[47]={p:"héng kàn chéng lǐng cè chéng fēng，yuǎn jìn gāo dī gè bù tóng。\nbù shí lú shān zhēn miàn mù，zhǐ yuán shēn zài cǐ shān zhōng。",t:"横看是山岭侧看是山峰，远近高低各不同。不认识庐山真面目，只因为身在这座山中。",k:[["横看","从正面看"],["侧","从侧面"],["缘","因为、由于"]],a:"这是一首哲理诗。前两句写庐山从不同角度看形态各异，后两句\"不识庐山真面目，只缘身在此山中\"由景入理，揭示了一个深刻的哲理：当局者迷，旁观者清。全诗写景与说理融为一体，既描绘了庐山的千姿百态，又蕴含了深刻的哲理，是宋诗以理入诗的代表作。"};
POEMS[48]={p:"shēng dāng zuò rén jié，sǐ yì wèi guǐ xióng。\nzhì jīn sī xiàng yǔ，bù kěn guò jiāng dōng。",t:"活着应当做人中豪杰，死了也要做鬼中英雄。至今思念项羽，不肯渡江东。",k:[["人杰","人中豪杰"],["鬼雄","鬼中英雄"],["江东","长江下游以东地区"]],a:"这是李清照南渡后所作。前两句掷地有声，表达了对人生价值的看法：生为人杰、死为鬼雄。后两句借项羽不肯过江东之事，讽刺南宋朝廷偏安苟且。全诗格调雄健，与其婉约词风形成鲜明对比，体现了李清照性格中刚烈的一面。"};
POEMS[49]={p:"sǐ qù yuán zhī wàn shì kōng，dàn bēi bù jiàn jiǔ zhōu tóng。\nwáng shī běi dìng zhōng yuán rì，jiā jì wú wàng gào nǎi wēng。",t:"死去本来就知道万事皆空，只是悲伤不见九州统一。王师北定中原之日，家祭不要忘记告诉你的父亲。",k:[["元知","本来就知道"],["九州","指中国"],["乃翁","你的父亲，指陆游自己"]],a:"这是陆游的绝笔诗。首句写死生之达观，次句写唯一遗憾是未见国家统一。后两句嘱咐儿子将来收复中原时家祭告之，表达了至死不渝的爱国情怀。全诗感情悲壮，质朴真挚，\"但悲不见九州同\"五字凝聚了诗人一生的遗憾与期盼。"};
POEMS[50]={p:"sān wàn lǐ hé dōng rù hǎi，wǔ qiān rèn yuè shàng mó tiān。\nyí mín lèi jìn hú chén lǐ，nán wàng wáng shī yòu yī nián。",t:"三万里黄河东流入海，五千仞岳上摩天。遗民泪尽在胡尘里，南望王师又一年。",k:[["仞","八尺为一仞"],["摩天","接触天，极言其高"],["遗民","指金人统治区的汉族人民"]],a:"这是一首爱国诗。前两句以黄河、华山极写中原山川的壮伟，后两句写遗民在胡尘中苦盼王师。\"泪尽\"二字尤为沉痛，\"又一年\"写出盼望之久。全诗将壮阔的山河与悲苦的遗民对比，表达了对收复中原的渴望和对南宋朝廷的不满。"};
POEMS[51]={p:"zhòu chū yún tián yè jì má，cūn zhuāng ér nǚ gè dāng jiā。\ntóng sūn wèi jiě gōng zhī zhī，yě bàng sāng yīn xué zhòng guā。",t:"白天出去耘田夜晚绩麻，村庄儿女各自当家。小孙未解耕织之事，也傍在桑阴下学种瓜。",k:[["耘田","除草"],["绩麻","搓麻线"],["供","从事、参加"]],a:"这是一首田园诗，描写了农村夏日的劳动场景。前两句写男女各司其职、辛勤劳作，后两句写小孙虽不会耕织却也在桑阴下学种瓜，充满童趣。全诗展现了一幅生动的农村生活画面，既有劳动的繁忙，又有生活的情趣，体现了范成大田园诗的特色。"};
POEMS[52]={p:"shèng rì xún fāng sì shuǐ bīn，wú biān guāng jǐng yī shí xīn。\nděng xián shí dé dōng fēng miàn，wàn zǐ qiān hóng zǒng shì chūn。",t:"好日子寻芳在泗水之滨，无边光景一时焕然一新。等闲识得东风的面目，万紫千红都是春色。",k:[["胜日","好日子，指春日"],["泗水","在山东曲阜"],["等闲","轻易、随便"]],a:"这是一首春游诗，也是一首哲理诗。前两句写春日郊游所见无边春景，后两句\"等闲识得东风面，万紫千红总是春\"由景入理，表面写春风催生万紫千红，实则暗喻读书明理后豁然开朗的境界。全诗将写景与说理融为一体，是宋诗\"以理入诗\"的典型。"};
POEMS[53]={p:"bàn mǔ fāng táng yī jiàn kāi，tiān guāng yún yǐng gòng pái huái。\nwèn qú nà dé qīng rú xǔ？wèi yǒu yuán tóu huó shuǐ lái。",t:"半亩大的方塘像一面镜子打开，天光云影共在水中徘徊。问它怎么这样清澈？因为有源头活水来。",k:[["鉴","镜子"],["渠","它，指方塘"],["如许","如此、这样"],["活水","流动的源头水"]],a:"这是一首哲理诗，以方塘水清喻读书明理。前两句写方塘清澈如镜，天光云影倒映其中。后两句\"问渠那得清如许，为有源头活水来\"由景入理，揭示了一个深刻的哲理：只有不断补充新知识，才能保持思想的清新和活力。全诗比喻巧妙，说理形象，是劝学诗中的名篇。"};
POEMS[54]={p:"shān wài qīng shān lóu wài lóu，xī hú gē wǔ jǐ shí xiū？\nnuǎn fēng xūn dé yóu rén zuì，zhí bǎ háng zhōu zuò biàn zhōu。",t:"山外有青山楼外有楼，西湖歌舞何时才休？暖风熏得游人沉醉，直把杭州当成了汴州。",k:[["几时休","什么时候停止"],["熏","熏染、吹拂"],["汴州","北宋都城，今开封"]],a:"这是一首政治讽刺诗。首句\"山外青山楼外楼\"写西湖山水之美，次句\"西湖歌舞几时休\"讽刺统治者沉迷享乐。后两句\"暖风熏得游人醉，直把杭州作汴州\"尤为辛辣，讽刺南宋统治者忘却故都、偏安苟且。全诗含蓄而深刻，是南宋爱国诗中的名篇。"};
POEMS[55]={p:"yīng lián jī chǐ yìn cāng tái，xiǎo kòu chái fēi jiǔ bù kāi。\nchūn sè mǎn yuán guān bù zhù，yī zhī hóng xìng chū qiáng lái。",t:"应怜惜木屐齿印了苍苔，轻叩柴门久不开。春色满园关不住，一枝红杏伸出墙来。",k:[["屐齿","木屐的齿印"],["柴扉","柴门"],["关不住","关锁不住"]],a:"这是一首游园不遇的诗。前两句写访友不遇，轻叩柴门而不开。后两句\"春色满园关不住，一枝红杏出墙来\"是千古名句，以一枝红杏出墙暗示园内春色满园，以小见大，以局部见全局。全诗从失望到惊喜，感情起伏有致，语言清新，意境优美。"};
POEMS[56]={p:"lǜ biàn shān yuán bái mǎn chuān，zǐ guī shēng lǐ yǔ rú yān。\nxiāng cūn sì yuè xián rén shǎo，cái liǎo cán sāng yòu chā tián。",t:"绿遍山原白满川，子规声中雨如烟。乡村四月闲人少，才了蚕桑又插田。",k:[["山原","山陵和原野"],["白满川","指水满川白"],["子规","杜鹃鸟"]],a:"这首诗描写了江南乡村四月的农忙景象。前两句以绿白色彩和子规烟雨写景，后两句写农人繁忙。全诗风格清新，充满生活气息。"};
POEMS[57]={p:"wǒ jiā xǐ yàn chí tóu shù，duǒ duǒ huā kāi dàn mò hén。\nbù yào rén kuā hǎo yán sè，zhǐ liú qīng qì mǎn qián kūn。",t:"我家洗砚池边的树，朵朵花开带着淡墨痕。不要人夸好颜色，只留清气满乾坤。",k:[["洗砚池","写字洗砚的水池"],["清气","清香的气味，也喻高洁品格"],["乾坤","天地"]],a:"这是一首题画咏物诗。前两句写墨梅的颜色淡雅，后两句借梅言志，\"只留清气满乾坤\"表达了不媚世俗、坚守高洁品格的精神。全诗托物言志，物我合一。"};
POEMS[58]={p:"qiān chuí wàn záo chū shēn shān，liè huǒ fén shāo ruò děng xián。\nfěn gǔ suì shēn hún bù pà，yào liú qīng bái zài rén jiān。",t:"千锤万凿从深山采出，烈火焚烧如同平常。粉骨碎身全不怕，要留清白在人间。",k:[["等闲","平常、寻常"],["清白","指石灰的白色，也喻人的清白品格"]],a:"这是一首咏物言志诗。以石灰自喻，\"千锤万凿\"\"烈火焚烧\"喻经历的磨炼，\"粉骨碎身浑不怕\"表达不怕牺牲的精神，\"要留清白在人间\"表明坚守节操的决心。全诗托物言志，气势铿锵。"};
POEMS[59]={p:"yáng liǔ qīng qīng jiāng shuǐ píng，wén láng jiāng shàng tà gē shēng。\ndōng biān rì chū xī biān yǔ，dào shì wú qíng què yǒu qíng。",t:"杨柳青青江水平，听到郎在江上踏歌声。东边日出西边下雨，说是无晴却有晴。",k:[["踏歌","唱歌时以足踏地"],["晴","双关语，谐音\"情\""]],a:"这是一首仿民歌的抒情诗。前两句写江边踏歌传情，后两句以\"晴\"双关\"情\"，巧妙地表达了少女对爱情的微妙感受。全诗风格清新活泼，运用双关修辞，富有民歌情调。"};
POEMS[60]={p:"dài zōng fū rú hé？qí lǔ qīng wèi liǎo。\nzào huà zhōng shén xiù，yīn yáng gē hūn xiǎo。\ndàng xiōng shēng céng yún，jué zì rù guī niǎo。\nhuì dāng líng jué dǐng，yī lǎn zhòng shān xiǎo。",t:"泰山究竟如何？齐鲁大地青翠绵延。造化钟聚神秀，阴阳割分昏晓。荡胸生层云，决眦入归鸟。定当登上最高顶，一览众山小。",k:[["岱宗","泰山"],["夫如何","究竟如何"],["钟神秀","聚集了神奇秀美"],["决眦","眼角几乎裂开"]],a:"这是杜甫青年时所作。前六句写远望、近望泰山之雄伟，末两句\"会当凌绝顶，一览众山小\"抒发攀登绝顶的壮志豪情。全诗气象阔大，格调昂扬，体现了诗人年轻时的雄心壮志。"};
POEMS[61]={p:"guó pò shān hé zài，chéng chūn cǎo mù shēn。\ngǎn shí huā jiàn lèi，hèn bié niǎo jīng xīn。\nfēng huǒ lián sān yuè，jiā shū dǐ wàn jīn。\nbái tóu sāo gèng duǎn，hún yù bù shèng zān。",t:"国破山河仍在，城春草木深茂。感时花溅泪，恨别鸟惊心。烽火连三月，家书抵万金。白头越搔越短，简直插不住簪。",k:[["感时","感叹时事"],["烽火","战火"],["抵万金","值万金，极言其珍贵"]],a:"这是杜甫陷于安史叛军时所作。首联写国破城春之景，颔联以花鸟写感时恨别之情，颈联写战乱中思念家人，尾联写白发稀短。全诗将家国之痛与个人之悲融为一体，沉郁顿挫，是杜诗\"诗史\"的代表作。"};
POEMS[62]={p:"fēng jí tiān gāo yuán xiào āi，zhǔ qīng shā bái niǎo fēi huí。\nwú biān luò mù xiāo xiāo xià，bù jìn cháng jiāng gǔn gǔn lái。\nwàn lǐ bēi qiū cháng zuò kè，bǎi nián duō bìng dú dēng tái。\njiān nán kǔ hèn fán shuāng bìn，liáo dǎo xīn tíng zhuó jiǔ bēi。",t:"风急天高猿啸哀，渚清沙白鸟飞回。无边落叶萧萧下，不尽长江滚滚来。万里悲秋常作客，百年多病独登台。艰难苦恨繁霜鬓，潦倒新停浊酒杯。",k:[["落木","落叶"],["萧萧","风吹落叶声"],["作客","客居他乡"],["繁霜鬓","白发增多"]],a:"这是杜甫晚年登高所作，被誉为\"古今七律第一\"。前四句写秋景，后四句抒怀。\"无边落木萧萧下，不尽长江滚滚来\"气象宏阔，将自然之秋与人生之秋融为一体。全诗沉郁悲凉，对仗工稳，是杜诗集大成之作。"};
POEMS[63]={p:"xī rén yǐ chéng huáng hè qù，cǐ dì kōng yú huáng hè lóu。\nhuáng hè yī qù bù fù fǎn，bái yún qiān zǎi kōng yōu yōu。\nqíng chuān lì lì hàn yáng shù，fāng cǎo qī qī yīng wǔ zhōu。\nrì mù xiāng guān hé chù shì？yān bō jiāng shàng shǐ rén chóu。",t:"昔人已乘黄鹤去，此地空余黄鹤楼。黄鹤一去不复返，白云千载空悠悠。晴川历历汉阳树，芳草萋萋鹦鹉洲。日暮乡关何处是？烟波江上使人愁。",k:[["昔人","指传说中乘鹤仙人"],["历历","分明的样子"],["萋萋","茂盛的样子"],["乡关","故乡"]],a:"这是崔颢登黄鹤楼所作，被严羽评为唐人七律第一。前四句由传说写起，抒发物是人非之感。后四句写登楼所见及日暮思乡之情。全诗气势恢宏，意境深远，\"黄鹤\"三次出现而不觉重复，自然流转。"};
POEMS[64]={p:"jǐn sè wú duān wǔ shí xián，yī xián yī zhù sī huá nián。\nzhuāng shēng xiǎo mèng mí hú dié，wàng dì chūn xīn tuō dù juān。\ncāng hǎi yuè míng zhū yǒu lèi，lán tián rì nuǎn yù shēng yān。\ncǐ qíng kě dài chéng zhuī yì？zhǐ shì dāng shí yǐ wǎng rán。",t:"锦瑟无端五十弦，一弦一柱思华年。庄生晓梦迷蝴蝶，望帝春心托杜鹃。沧海月明珠有泪，蓝田日暖玉生烟。此情可待成追忆？只是当时已惘然。",k:[["锦瑟","装饰华美的瑟"],["无端","没有来由"],["惘然","失意的样子"]],a:"这是李商隐的代表作，也是唐诗中最难解的一首。诗中用了庄周梦蝶、望帝啼鹃、沧海珠泪、蓝田玉烟四个典故，追忆逝去的华年与爱情。\"此情可待成追忆，只是当时已惘然\"为千古名句，表达了追忆往事时的怅惘之情。全诗意境朦胧，辞采华美。"};
POEMS[65]={p:"xiāng jiàn shí nán bié yì nán，dōng fēng wú lì bǎi huā cán。\nchūn cán dào sǐ sī fāng jìn，là jù chéng huī lèi shǐ gān。\nxiǎo jìng dàn chóu yún bìn gǎi，yè yín yīng jué yuè guāng hán。\npéng shān cǐ qù wú duō lù，qīng niǎo yīn qín wèi tàn kàn。",t:"相见时难别亦难，东风无力百花残。春蚕到死丝方尽，蜡炬成灰泪始干。晓镜但愁云鬓改，夜吟应觉月光寒。蓬山此去无多路，青鸟殷勤为探看。",k:[["丝方尽","丝双关\"思\""],["蓬山","蓬莱山，仙境"],["青鸟","西王母使者，传信使者"]],a:"这是一首爱情诗。\"春蚕到死丝方尽，蜡炬成灰泪始干\"是千古名句，以春蚕蜡炬喻至死不渝的爱情。全诗用典精当，情感深沉，将相思之苦与别离之恨表达得缠绵悱恻。"};
POEMS[66]={p:"jūn wèn guī qī wèi yǒu qī，bā shān yè yǔ zhǎng qiū chí。\nhé dāng gòng jiǎn xī chuāng zhú，què huà bā shān yè yǔ shí。",t:"你问归期未有定期，巴山夜雨涨满秋池。何时共同剪西窗烛，却话巴山夜雨时。",k:[["何当","何时能够"],["剪烛","剪去烛芯，使烛明亮"],["却话","回头说、再谈起"]],a:"这是一首寄给北方妻子的诗。首句写归期未定，次句写巴山夜雨之景。后两句\"何当共剪西窗烛，却话巴山夜雨时\"由眼前想象未来重逢时共话今宵，虚实结合，时空交错。全诗构思巧妙，语言朴素而情感深挚。"};
POEMS[67]={p:"kè lù qīng shān wài，xíng zhōu lǜ shuǐ qián。\ncháo píng liǎng àn kuò，fēng zhèng yī fān xuán。\nhǎi rì shēng cán yè，jiāng chūn rù jiù nián。\nxiāng shū hé chù dá？guī yàn luò yáng biān。",t:"客路在青山之外，行舟在绿水之前。潮平两岸宽阔，风正一帆高悬。海日生残夜，江春入旧年。乡书何处送达？归雁洛阳边。",k:[["客路","旅途"],["残夜","将尽的夜"],["旧年","过去的一年"]],a:"这是王湾途经北固山时所作。\"海日生残夜，江春入旧年\"为千古名句，写海上旭日从残夜中升起，江上春意闯入旧年，蕴含时序交替的理趣。全诗写景壮阔，抒情含蓄，宰相张九龄曾手书此联于政事堂。"};
POEMS[68]={p:"gū shān sì běi jiǎ tíng xī，shuǐ miàn chū píng yún jiǎo dī。\njǐ chù zǎo yīng zhēng nuǎn shù，shuí jiā xīn yàn zhuó chūn ní。\nluàn huā jiàn yù mí rén yǎn，qiǎn cǎo cái néng mò mǎ tí。\nzuì ài hú dōng xíng bù zú，lǜ yáng yīn lǐ bái shā dī。",t:"孤山寺北贾亭西，水面初平云脚低。几处早莺争暖树，谁家新燕啄春泥。乱花渐欲迷人眼，浅草才能没马蹄。最爱湖东行不足，绿杨阴里白沙堤。",k:[["云脚低","云气低垂水面"],["争暖树","争着飞向向阳的树"],["没","遮没、淹没"]],a:"这是白居易任杭州刺史时所作。全诗描绘了西湖早春的明媚风光：水平云低、莺争燕啄、花迷人眼、草没马蹄。语言平易流畅，画面生动明丽，表达了诗人对西湖春色的喜爱之情。"};
POEMS[69]={p:"dān chē yù wèn biān，shǔ guó guò jū yán。\nzhēng péng chū hàn sài，guī yàn rù hú tiān。\ndà mò gū yān zhí，cháng hé luò rì yuán。\nxiāo guān féng hòu qì，dōu hù zài yàn rán。",t:"单车欲问边，属国过居延。征蓬出汉塞，归雁入胡天。大漠孤烟直，长河落日圆。萧关逢候骑，都护在燕然。",k:[["征蓬","随风远行的蓬草，自喻"],["孤烟直","烽烟在无风中直升"],["长河","黄河"]],a:"这是王维出使边塞时所作。\"大漠孤烟直，长河落日圆\"是千古名句，以\"直\"\"圆\"二字写大漠烽烟和长河落日，画面壮阔，构图精妙，被王国维评为\"千古壮观\"。全诗将叙事、写景、抒情融为一体。"};
POEMS[70]={p:"bā shān chǔ shuǐ qī liáng dì，èr shí sān nián qì zhì shēn。\nhuái jiù kōng yín wén dí fù，dào xiāng fān sì lǎn kē rén。\nchén zhōu cè pàn qiān fān guò，bìng shù qián tou wàn mù chūn。\njīn rì tīng jūn gē yī qǔ，zàn píng bēi jiǔ zhǎng jīng shén。",t:"巴山楚水凄凉之地，二十三年弃置身。怀旧空吟闻笛赋，到乡翻似烂柯人。沉舟侧畔千帆过，病树前头万木春。今日听君歌一曲，暂凭杯酒长精神。",k:[["弃置身","被弃置不用的人"],["闻笛赋","晋向秀听笛思友之作"],["烂柯人","王质观棋烂柯的典故"]],a:"这是刘禹锡酬答白居易的诗。\"沉舟侧畔千帆过，病树前头万木春\"为千古名句，以沉舟病树自喻，却写出千帆竞发、万木争春的景象，表达了豁达乐观的精神。全诗虽写贬谪之苦，却格调昂扬。"};
POEMS[71]={p:"hào dàng lí chóu bái rì xié，yín biān dōng zhǐ jí tiān yá。\nluò hóng bú shì wú qíng wù，huà zuò chūn ní gèng hù huā。",t:"浩荡离愁白日斜，吟鞭东指即天涯。落红不是无情物，化作春泥更护花。",k:[["浩荡","广阔无边的样子"],["吟鞭","诗人的马鞭"],["落红","落花"]],a:"这是龚自珍辞官南归时所作。\"落红不是无情物，化作春泥更护花\"为千古名句，以落花自喻，表达辞官后仍关心国事、愿为后代奉献的精神。全诗将离愁与壮志结合，格调悲慨而积极。"};
POEMS[72]={p:"chéng què fǔ sān qín，fēng yān wàng wǔ jīn。\nyǔ jūn lí bié yì，tóng shì huàn yóu rén。\nhǎi nèi cún zhī jǐ，tiān yá ruò bǐ lín。\nwú wéi zài qí lù，ér nǚ gòng zhān jīn。",t:"城阙辅三秦，风烟望五津。与君离别意，同是宦游人。海内存知己，天涯若比邻。无为在歧路，儿女共沾巾。",k:[["城阙","指长安"],["三秦","长安一带"],["五津","四川岷江五大渡口"],["歧路","岔路口"]],a:"这是王勃送别友人的诗。\"海内存知己，天涯若比邻\"为千古名句，一扫送别诗的悲酸之态，格调高昂，意境开阔，表达了真挚友情不受时空限制的豁达情怀。全诗起承转合，对仗工整，是初唐五律的代表作。"};
POEMS[73]={p:"bā yuè qiū gāo fēng nù háo，juǎn wǒ wū shàng sān chóng máo。",t:"八月秋高风怒号，卷我屋上三重茅。",k:[["秋高","秋天天高气爽"],["三重茅","三层茅草"]],a:"这是杜甫居住成都草堂时所作。全诗描写秋风破屋、群童抱茅、夜雨湿漏的苦况，最后推己及人，发出\"安得广厦千万间，大庇天下寒士俱欢颜\"的宏愿。全诗写实与抒情结合，体现了杜甫忧国忧民的伟大胸怀。"};
POEMS[74]={p:"běi fēng juǎn dì bái cǎo zhé，hú tiān bā yuè jí fēi xuě。\nhū rú yī yè chūn fēng lái，qiān shù wàn shù lí huā kāi。",t:"北风卷地白草折，胡天八月即飞雪。忽然如一夜春风来，千树万树梨花开。",k:[["白草折","白草被风吹折"],["胡天","指西北地区天空"]],a:"这是岑参送别武判官归京的边塞诗。\"忽然如一夜春风来，千树万树梨花开\"为千古名句，以梨花喻雪花，将苦寒的边塞写得如春花烂漫，想象奇特。全诗将边塞奇寒与送别之情结合，格调奇丽。"};
POEMS[75]={p:"dōng lín jié shí，yǐ guān cāng hǎi。\nshuǐ hé dàn dàn，shān dǎo sǒng zhì。\nshù mù cóng shēng，bǎi cǎo fēng mào。\nqiū fēng xiāo sè，hóng bō yǒng qǐ。\nrì yuè zhī xíng，ruò chū qí zhōng；\nxīng hàn càn làn，ruò chū qí lǐ。\nxìng shèn zhì zāi，gē yǐ yǒng zhì。",t:"东临碣石，以观沧海。水何澹澹，山岛竦峙。树木丛生，百草丰茂。秋风萧瑟，洪波涌起。日月之行，若出其中；星汉灿烂，若出其里。幸甚至哉，歌以咏志。",k:[["碣石","山名，在河北"],["澹澹","水波荡漾的样子"],["星汉","银河"]],a:"这是曹操北征乌桓途中登碣石山所作。\"日月之行，若出其中；星汉灿烂，若出其里\"以沧海吞吐日月星辰的想象，表达了统一天下的雄心壮志。全诗气象雄浑，格调苍凉，是建安诗歌的代表作。"};
POEMS[76]={p:"jié lú zài rén jìng，ér wú chē mǎ xuān。\nwèn jūn hé néng ěr？xīn yuǎn dì zì piān。\ncǎi jú dōng lí xià，yōu rán jiàn nán shān。\nshān qì rì xī jiā，fēi niǎo xiāng yǔ huán。\ncǐ zhōng yǒu zhēn yì，yù biàn yǐ wàng yán。",t:"结庐在人境，而无车马喧。问君何能尔？心远地自偏。采菊东篱下，悠然见南山。山气日夕佳，飞鸟相与还。此中有真意，欲辨已忘言。",k:[["结庐","建造房屋"],["人境","人间、人聚居之处"],["尔","如此、这样"]],a:"这是陶渊明归隐后的代表作。\"采菊东篱下，悠然见南山\"为千古名句，写采菊时无意望见南山，物我两忘的境界。全诗表现了弃官归隐后恬淡闲适的心境和对自然的热爱，是山水田园诗的典范。"};
POEMS[77]={p:"shǎo wú shì sú yùn，xìng běn ài qiū shān。\nwù luò chén wǎng zhōng，yī qù sān shí nián。\njī niǎo liàn jiù lín，chí yú sī gù yuān。\nkāi huāng nán yě jì，shǒu zhuō guī yuán tián。",t:"少无适俗韵，性本爱丘山。误落尘网中，一去三十年。羁鸟恋旧林，池鱼思故渊。开荒南野际，守拙归园田。",k:[["适俗韵","适应世俗的气质"],["尘网","尘世的罗网，指仕途"],["羁鸟","笼中鸟"],["守拙","保持淳朴的本性"]],a:"这是陶渊明辞彭泽令归隐后所作。全诗以羁鸟池鱼自喻，表达了误入仕途的悔恨和归隐田园的喜悦。\"羁鸟恋旧林，池鱼思故渊\"为名句，比喻贴切。全诗语言朴素自然，感情真挚，开创了田园诗派。"};
POEMS[78]={p:"jīn zūn qīng jiǔ dǒu shí qiān，yù pán zhēn xiū zhí wàn qián。\ntíng bēi tóu zhù bù néng shí，bá jiàn sì gù xīn máng rán。\nyù dù huáng hé bīng sāi chuān，jiāng dēng tài xíng xuě mǎn shān。\nxián lái chuí diào bì xī shàng，hū fù chéng zhōu mèng rì biān。\nxíng lù nán！xíng lù nán！duō qí lù，jīn ān zài？\ncháng fēng pò làng huì yǒu shí，zhí guà yún fān jì cāng hǎi。",t:"金樽清酒斗十千，玉盘珍羞直万钱。停杯投箸不能食，拔剑四顾心茫然。欲渡黄河冰塞川，将登太行雪满山。闲来垂钓碧溪上，忽复乘舟梦日边。行路难！行路难！多歧路，今安在？长风破浪会有时，直挂云帆济沧海。",k:[["投箸","放下筷子"],["冰塞川","冰封了黄河"],["歧路","岔路"]],a:"这是李白离开长安时所作。\"长风破浪会有时，直挂云帆济沧海\"为千古名句，表达了虽遭遇挫折但仍坚信理想终能实现的豪迈气概。全诗跌宕起伏，将苦闷与自信交替写出，体现了李白诗歌豪放飘逸的风格。"};
POEMS[79]={p:"guān guān jū jiū，zài hé zhī zhōu。\nyǎo tiǎo shū nǚ，jūn zǐ hǎo qiú。",t:"关关和鸣的雎鸠，栖息在河中沙洲。美丽贤淑的女子，是君子的好配偶。",k:[["关关","鸟鸣声"],["雎鸠","一种水鸟"],["窈窕","文静美好的样子"],["好逑","好的配偶"]],a:"这是《诗经》的第一篇，也是中国诗歌的开篇之作。描写男子对采荇菜女子的爱慕追求。\"窈窕淑女，君子好逑\"为千古名句。全诗以雎鸠和鸣起兴，反复咏唱，运用赋比兴手法，奠定了中国诗歌的传统。"};
POEMS[80]={p:"jiān jiā cāng cāng，bái lù wéi shuāng。\nsuǒ wèi yī rén，zài shuǐ yī fāng。",t:"芦苇苍苍，白露凝成霜。所谓那人，在水的那一方。",k:[["蒹葭","芦苇"],["伊人","那个人"],["一方","另一边"]],a:"这是《诗经·秦风》中的名篇，描写对心上人的追求与思念。\"所谓伊人，在水一方\"为千古名句，写可望而不可即的意境。全诗以景起兴，反复咏唱，营造了朦胧凄美的意境，是《诗经》中最具艺术性的作品之一。"};
POEMS[81]={p:"gù rén jù jī shǔ，yāo wǒ zhì tián jiā。\nlǜ shù cūn biān hé，qīng shān guō wài xié。\nkāi xuān miàn chǎng pǔ，bǎ jiǔ huà sāng má。\ndài dào chóng yáng rì，hái lái jiù jú huā。",t:"故人准备了鸡和黍，邀请我到田家。绿树环绕村边，青山在城郭外斜立。开窗面对场院菜圃，把酒谈论桑麻。等到重阳节，还来赏菊花。",k:[["具","准备、办"],["轩","窗"],["场圃","打谷场和菜园"]],a:"这是孟浩然过友人田庄时所作。全诗描写了田园生活的恬静和友情的真挚。\"绿树村边合，青山郭外斜\"写景如画。全诗不事雕琢，自然恬淡，体现了孟浩然诗\"淡而有味\"的特色。"};
POEMS[82]={p:"tiān jiē xiǎo yǔ rùn rú sū，cǎo sè yáo kàn jìn què wú。\nzuì shì yī nián chūn hǎo chù，jué shèng yān liǔ mǎn huáng dū。",t:"天街小雨润如酥，草色遥看近却无。最是一年春好处，绝胜烟柳满皇都。",k:[["天街","京城街道"],["酥","酥酪，喻细滑"],["绝胜","远远胜过"]],a:"这是韩愈写给张籍的早春诗。\"草色遥看近却无\"写早春草色若隐若现的微妙感觉，观察入微。全诗赞美早春清新之美，胜过暮春烟柳。格调清新，体物入微。"};
POEMS[83]={p:"yín zhú qiū guāng lěng huà píng，qīng luó xiǎo shàn pū liú yíng。\ntiān jiē yè sè liáng rú shuǐ，wò kàn qiān niú zhī nǚ xīng。",t:"银烛秋光冷画屏，轻罗小扇扑流萤。天阶夜色凉如水，卧看牵牛织女星。",k:[["画屏","有画饰的屏风"],["流萤","飞动的萤火虫"],["天阶","宫廷台阶"]],a:"这是一首描写宫女秋夜生活的诗。前两句写宫女以扇扑萤的孤寂，后两句写卧看双星的怅惘。全诗不着一个怨字，却处处透出幽怨，含蓄深婉。"};
POEMS[84]={p:"fēi lái shān shàng qiān xún tǎ，wén shuō jī míng jiàn rì shēng。\nbù wèi fú yún zhē wàng yǎn，zì yuán shēn zài zuì gāo céng。",t:"飞来山上千寻塔，听说鸡鸣见日升。不畏浮云遮望眼，自缘身在最高层。",k:[["千寻","极言其高"],["浮云","暗喻蒙蔽君主的奸佞"],["缘","因为"]],a:"这是王安石登飞来峰时所作。\"不畏浮云遮望眼，自缘身在最高层\"为千古名句，表面写登高望远，实则表达推行新法、不畏奸邪的政治抱负。全诗借景抒怀，格调高昂。"};
POEMS[85]={p:"jiǔ zhōu shēng qì shì fēng léi，wàn mǎ qí yīn jiū kě āi。\nwǒ quàn tiān gōng chóng dǒu sǒu，bù jū yī gé jiàng rén cái。",t:"九州生气恃风雷，万马齐喑究可哀。我劝天公重抖擞，不拘一格降人才。",k:[["恃","依靠"],["万马齐喑","比喻人们不敢讲话"],["抖擞","振作精神"]],a:"这是龚自珍路过镇江时所作。\"我劝天公重抖擞，不拘一格降人才\"为千古名句，表达了对社会沉闷的不满和对变革人才的渴望。全诗气势磅礴，寓意深远。"};
POEMS[86]={p:"shuí jiā yù dí àn fēi shēng，sàn rù chūn fēng mǎn luò chéng。\ncǐ yè qǔ zhōng wén zhé liǔ，hé rén bù qǐ gù yuán qíng。",t:"谁家玉笛暗飞声，散入春风满洛城。此夜曲中闻折柳，何人不起故园情。",k:[["暗飞声","暗中飘来声音"],["折柳","折杨柳曲，多抒离别之情"]],a:"这是李白在洛阳听笛时所作。前两句写笛声随风散满洛城，后两句由\"折柳\"曲引发思乡之情。全诗由听觉引起情感波动，含蓄深婉。"};
POEMS[87]={p:"chén qǐ dòng zhēng duó，kè xíng bēi gù xiāng。\njī shēng máo diàn yuè，rén jì bǎn qiáo shuāng。\nhú yè luò shān lù，zhǐ huā míng yì qiáng。\nyīn sī dù líng mèng，fú yàn mǎn huí táng。",t:"晨起动征铎，客行悲故乡。鸡声茅店月，人迹板桥霜。槲叶落山路，枳花明驿墙。因思杜陵梦，凫雁满回塘。",k:[["征铎","车行的铃声"],["茅店","茅草盖的客店"],["杜陵","在长安南，作者故乡"]],a:"这是温庭筠早行途中所作。\"鸡声茅店月，人迹板桥霜\"为千古名句，以六个名词组合，不用一个动词，便勾勒出早行图景。全诗对仗工整，意境凄清。"};
POEMS[88]={p:"huí lè fēng qián shā sì xuě，shòu jiàng chéng wài yuè rú shuāng。\nbù zhī hé chù chuī lú guǎn，yī yè zhēng rén jìn wàng xiāng。",t:"回乐烽前沙似雪，受降城外月如霜。不知何处吹芦管，一夜征人尽望乡。",k:[["回乐烽","回乐县的烽火台"],["芦管","芦笛"],["征人","戍边将士"]],a:"这是一首边塞诗。前两句以沙似雪、月如霜写边塞月夜的凄清，后两句写芦管声引发征人思乡。\"一夜征人尽望乡\"写思乡之情的普遍和深沉。全诗意境凄清，情致深婉。"};
POEMS[89]={p:"dú lián yōu cǎo jiàn biān shēng，shàng yǒu huáng lí shēn shù míng。\nchūn cháo dài yǔ wǎn lái jí，yě dù wú rén zhōu zì héng。",t:"独怜幽草涧边生，上有黄鹂深树鸣。春潮带雨晚来急，野渡无人舟自横。",k:[["独怜","只爱"],["幽草","深草"],["野渡","荒野渡口"]],a:"这是韦应物任滁州刺史时所作。\"野渡无人舟自横\"为千古名句，写荒野渡口无人，空船自在横斜的景象。全诗以动衬静，表现了恬淡闲适的心境和自然野趣。"};
POEMS[90]={p:"méi zǐ huáng shí rì rì qíng，xiǎo xī fàn jìn què shān xíng。\nlǜ yīn bù jiǎn lái shí lù，tiān dé huáng lí sì wǔ shēng。",t:"梅子黄时日日晴，小溪泛尽却山行。绿阴不减来时路，添得黄鹂四五声。",k:[["梅子黄时","江南梅雨季节，此时却说日日晴"],["泛尽","乘船走到尽头"]],a:"这是曾几游三衢山时所作。全诗写初夏山行之景：溪尽山行，绿阴不减，黄鹂添声。格调轻快，画面清新，表现了诗人闲适愉悦的心情。"};
POEMS[91]={p:"zì gǔ féng qiū bēi jì liáo，wǒ yán qiū rì shèng chūn zhāo。\nqíng kōng yī hè pái yún shàng，biàn yǐn shī qíng dào bì xiāo。",t:"自古逢秋悲寂寥，我言秋日胜春朝。晴空一鹤排云上，便引诗情到碧霄。",k:[["寂寥","寂寥空旷"],["排云","推开云层"],["碧霄","青天"]],a:"这是刘禹锡贬朗州时所作。一反悲秋传统，\"我言秋日胜春朝\"格调高昂。\"晴空一鹤排云上\"以白鹤冲天写秋日豪情。全诗气势开阔，表现了诗人虽遭贬谪却乐观豁达的精神。"};
POEMS[92]={p:"duì jiǔ dāng gē，rén shēng jǐ hé！\npì rú zhāo lù，qù rì kǔ duō。",t:"对酒当歌，人生几何！譬如朝露，去日苦多。",k:[["几何","多少"],["朝露","早晨的露水，喻短暂"],["苦多","恨多"]],a:"这是曹操《短歌行》的开篇。\"对酒当歌，人生几何\"感叹人生短暂。全诗以饮酒发端，抒发求贤若渴的心情和统一天下的壮志。\"周公吐哺，天下归心\"为结句，气魄宏大。"};
POEMS[93]={p:"tiáo tiáo qiān niú xīng，jiǎo jiǎo hé hàn nǚ。\nxiān xiān zhuó sù shǒu，zhá zhá nòng jī zhù。\nzhōng rì bù chéng zhāng，qì tì líng rú yǔ。",t:"迢迢牵牛星，皎皎河汉女。纤纤擢素手，札札弄机杼。终日不成章，泣涕零如雨。",k:[["迢迢","遥远的样子"],["皎皎","明亮的样子"],["擢","举、摆动"],["札札","织机声"]],a:"这是《古诗十九首》之一，以牛郎织女故事写男女离别之情。全诗借星象写人间离愁，\"终日不成章，泣涕零如雨\"写相思之苦。语言朴素而情感深挚。"};
POEMS[94]={p:"kōng shān xīn yǔ hòu，tiān qì wǎn lái qiū。\nmíng yuè sōng jiān zhào，qīng quán shí shàng liú。\nzhú xuān guī huàn nǚ，lián dòng xià yú zhōu。\nsuí yì chūn fāng xiē，wáng sūn zì kě liú。",t:"空山新雨后，天气晚来秋。明月松间照，清泉石上流。竹喧归浣女，莲动下渔舟。随意春芳歇，王孙自可留。",k:[["浣女","洗衣的女子"],["春芳歇","春天的芳华消歇"],["王孙","贵族子弟，自指"]],a:"这是王维隐居辋川时所作。\"明月松间照，清泉石上流\"为千古名句，写秋山月夜之清幽。全诗动静相衬，视听结合，将自然之美与隐居之乐融为一体，体现了\"诗中有画\"的特色。"};
POEMS[95]={p:"yī xū yán xū，wēi hū gāo zāi！\nshǔ dào zhī nán，nán yú shàng qīng tiān！",t:"噫吁嚱，危乎高哉！蜀道之难，难于上青天！",k:[["噫吁嚱","惊叹词"],["危","高"]],a:"这是李白初入长安送友人入蜀时所作。全诗以雄奇之笔描绘蜀道之险，从山势之高、道路之险、气氛之凄三个方面反复咏叹。\"蜀道之难，难于上青天\"三次出现，一唱三叹。全诗想象奇特，气势磅礴，是李白浪漫主义的代表作。"};
POEMS[96]={p:"jūn bú jiàn huáng hé zhī shuǐ tiān shàng lái，bēn liú dào hǎi bù fù huí。",t:"君不见黄河之水天上来，奔流到海不复回。",k:[["君不见","乐府常用语，请你看看"],["不复回","不再回来"]],a:"这是李白的代表作之一。\"君不见黄河之水天上来，奔流到海不复回\"以黄河起兴，感叹人生短暂。\"天生我材必有用，千金散尽还复来\"写自信豪迈。\"将进酒，杯莫停\"写痛饮狂欢。全诗气势豪迈，情感大起大落。"};
POEMS[97]={p:"chéng xiàng cí táng hé chù xún，jǐn guān chéng wài bǎi sēn sēn。\nyìng jiē bì cǎo zì chūn sè，gé yè huáng lí kōng hǎo yīn。\nsān gù pín fán tiān xià jì，liǎng cháo kāi jì lǎo chén xīn。\nchū shī wèi jié shēn xiān sǐ，cháng shǐ yīng xióng lèi mǎn jīn。",t:"丞相祠堂何处寻，锦官城外柏森森。映阶碧草自春色，隔叶黄鹂空好音。三顾频烦天下计，两朝开济老臣心。出师未捷身先死，长使英雄泪满襟。",k:[["丞相","指诸葛亮"],["三顾","刘备三顾茅庐"],["开济","开创基业、匡济危难"]],a:"这是杜甫凭吊武侯祠时所作。\"出师未捷身先死，长使英雄泪满襟\"为千古名句，写诸葛亮壮志未酬的悲剧。全诗将叙事、写景、抒情融为一体，表达了对诸葛亮的敬仰和惋惜。"};
POEMS[98]={p:"shè nán shè běi jiē chūn shuǐ，dàn jiàn qún ōu rì rì lái。\nhuā jìng bù céng yuán kè sǎo，péng mén jīn shǐ wèi jūn kāi。",t:"舍南舍北皆春水，但见群鸥日日来。花径不曾缘客扫，蓬门今始为君开。",k:[["花径","落花满径"],["蓬门","柴门，喻贫寒之家"]],a:"这是杜甫在成都草堂招待客人时所作。\"花径不曾缘客扫，蓬门今始为君开\"写为客人的到来而欣喜。全诗洋溢着好客的热情和生活的情趣，格调轻快。"};
POEMS[99]={p:"xī wén dòng tíng shuǐ，jīn shàng yuè yáng lóu。\nwú chǔ dōng nán chè，qián kūn rì yè fú。",t:"昔闻洞庭水，今上岳阳楼。吴楚东南坼，乾坤日夜浮。",k:[["坼","分裂、分开"],["乾坤","天地，此指日月天地"]],a:"这是杜甫登岳阳楼时所作。\"吴楚东南坼，乾坤日夜浮\"写洞庭湖的浩瀚壮阔，气象万千。全诗由景入情，将身世之悲与家国之忧融为一体。"};
POEMS[100]={p:"chūn jiāng cháo shuǐ lián hǎi píng，hǎi shàng míng yuè gòng cháo shēng。",t:"春江潮水连海平，海上明月共潮生。",k:[["潮水","涨潮之水"],["共潮生","随潮水一同升起"]],a:"这是张若虚的代表作，被誉为\"孤篇盖全唐\"。全诗以春江月夜为中心，描绘了月升、月高、月落的完整过程，将自然之美与人生哲理融为一体。\"江畔何人初见月？江月何年初照人\"为千古名问，意境空灵深远。"};
POEMS[101]={p:"xī sài shān qián bái lù fēi，táo huā liú shuǐ guì yú féi。\nqīng ruò lì，lǜ suō yī，xié fēng xì yǔ bù xū guī。",t:"西塞山前白鹭飞，桃花流水鳜鱼肥。青箬笠，绿蓑衣，斜风细雨不须归。",k:[["箬笠","竹叶编的斗笠"],["蓑衣","草编雨衣"]],a:"这是早期文人词中描写自然风光的名作。全词如一幅清新的春江钓图，色彩鲜明（白鹭、桃花、青笠、绿蓑），格调轻快，表现了隐逸生活的自在情趣。"};
POEMS[102]={p:"jiāng nán hǎo，fēng jǐng jiù céng ān。\nrì chū jiāng huā hóng shèng huǒ，chūn lái jiāng shuǐ lǜ rú lán。\nnéng bù yì jiāng nán？",t:"江南好，风景旧曾谙。日出江花红胜火，春来江水绿如蓝。能不忆江南？",k:[["谙","熟悉"],["胜","超过、胜过"]],a:"这是白居易晚年回忆杭州时所作。\"日出江花红胜火，春来江水绿如蓝\"以红绿对比写江南春色之美。全词语言清新，感情真挚，是忆江南的名篇。"};
POEMS[103]={p:"jiǔ qǔ huáng hé wàn lǐ shā，làng táo fēng bǒ zì tiān yá。\nrú jīn zhí shàng yín hé qù，tóng dào qiān niú zhī nǚ jiā。",t:"九曲黄河万里沙，浪淘风簸自天涯。如今直上银河去，同到牵牛织女家。",k:[["簸","簸荡"],["天涯","天边"]],a:"这是刘禹锡浪淘沙组诗之一。后两句以浪漫想象写乘浪直上银河、寻访牛女，由黄河联想到天上银河。全诗气势豪迈，想象丰富。"};
POEMS[104]={p:"shū xǐ bà，dú yǐ wàng jiāng lóu。\nguò jìn qiān fān jiē bú shì，xié huī mò mò shuǐ yōu yōu。\ncháng duàn bái píng zhōu。",t:"梳洗罢，独倚望江楼。过尽千帆皆不是，斜晖脉脉水悠悠。肠断白蘋洲。",k:[["脉脉","含情凝视的样子"],["白蘋洲","长满白蘋的水中小洲"]],a:"这是温庭筠的代表作。写女子登楼望江盼归人，\"过尽千帆皆不是\"写盼望之切与失望之深。全词含蓄深婉，是花间词的代表作。"};
POEMS[105]={p:"wú yán dú shàng xī lóu，yuè rú gōu。\njì mò wú tóng shēn yuàn suǒ qīng qiū。\njiǎn bú duàn，lǐ huán luàn，shì lí chóu。\nbié shì yī bān zī wèi zài xīn tóu。",t:"无言独上西楼，月如钩。寂寞梧桐深院锁清秋。剪不断，理还乱，是离愁。别是一般滋味在心头。",k:[["锁","锁住、深锁"],["离愁","去国之愁"]],a:"这是李煜降宋后所作。\"剪不断，理还乱\"以丝喻愁，将抽象的愁绪化为可触可感之物。全词写亡国之痛，语言朴素而感情深挚，是李煜词的代表作。"};
POEMS[106]={p:"chūn huā qiū yuè hé shí liǎo？wǎng shì zhī duō shǎo。\nxiǎo lóu zuó yè yòu dōng fēng，gù guó bù kān huí shǒu yuè míng zhōng。\ndiāo lán yù qì yīng yóu zài，zhǐ shì zhū yán gǎi。\nwèn jūn néng yǒu jǐ duō chóu？qià sì yī jiāng chūn shuǐ xiàng dōng liú。",t:"春花秋月何时了？往事知多少。小楼昨夜又东风，故国不堪回首月明中。雕栏玉砌应犹在，只是朱颜改。问君能有几多愁？恰似一江春水向东流。",k:[["了","了结、终结"],["故国","指南唐故都"],["朱颜","红颜，此指容颜"]],a:"这是李煜的绝命词。\"问君能有几多愁？恰似一江春水向东流\"为千古名句，以春水喻愁，将无形的愁化为有形的江流。全词将亡国之痛写得淋漓尽致，是李煜词的巅峰之作。"};
POEMS[107]={p:"lián wài yǔ chán chán，chūn yì lán shān。\nluó qīn bù nài wǔ gēng hán。\nmèng lǐ bù zhī shēn shì kè，yī shǎng tān huān。",t:"帘外雨潺潺，春意阑珊。罗衾不耐五更寒。梦里不知身是客，一晌贪欢。",k:[["阑珊","衰残、将尽"],["罗衾","丝绸被子"],["一晌","片刻、一时"]],a:"这是李煜降宋后所作。\"梦里不知身是客，一晌贪欢\"写梦中暂忘亡国之痛，醒来更增悲凉。全词以梦与醒对比，写亡国之痛，含蓄深婉。"};
POEMS[108]={p:"sài xià qiū lái fēng jǐng yì，héng yáng yàn qù wú liú yì。\nsì miàn biān shēng lián jiǎo qǐ，qiān zhàng lǐ，cháng yān luò rì gū chéng bì。",t:"塞下秋来风景异，衡阳雁去无留意。四面边声连角起，千嶂里，长烟落日孤城闭。",k:[["风景异","风景与内地不同"],["边声","边塞特有的声音"],["嶂","像屏障的山峰"]],a:"这是范仲淹守边时所作，开宋词豪放风气。\"长烟落日孤城闭\"写边塞的荒凉孤寂。全词将边塞风光与思乡之情结合，格调悲壮。"};
POEMS[109]={p:"yī qǔ xīn cí jiǔ yī bēi，qù nián tiān qì jiù tíng tái。\nxī yáng xī xià jǐ shí huí？\nwú kě nài hé huā luò qù，sì céng xiāng shí yàn guī lái。\nxiǎo yuán xiāng jìng dú pái huái。",t:"一曲新词酒一杯，去年天气旧亭台。夕阳西下几时回？无可奈何花落去，似曾相识燕归来。小园香径独徘徊。",k:[["无可奈何","没有办法、不得已"]],a:"这是晏殊的代表作。\"无可奈何花落去，似曾相识燕归来\"为千古名句，对仗工整，含哲理意味，写花落燕归、时光流逝之感。全词温润秀洁，是婉约词的典范。"};
POEMS[110]={p:"shān xià lán yá duǎn jìn xī，sōng jiān shā lù jìng wú ní。\nxiāo xiāo mù yǔ zǐ guī tí。\nshuí dào rén shēng wú zài shǎo？mén qián liú shuǐ shàng néng xī！\nxiū jiāng bái fà chàng huáng jī。",t:"山下兰芽短浸溪，松间沙路净无泥。潇潇暮雨子规啼。谁道人生无再少？门前流水尚能西！休将白发唱黄鸡。",k:[["再少","重返年少"],["黄鸡","喻时光流逝"]],a:"这是苏轼贬黄州时所作。\"谁道人生无再少？门前流水尚能西\"反用\"水东流\"之意，表达不服老的乐观精神。全词格调昂扬，体现了苏轼旷达的人生态度。"};
POEMS[111]={p:"jiàn jú chóu yān lán qì lù，luó mù qīng hán，yàn zi shuāng fēi qù。\nmíng yuè bù ān lí hèn kǔ，xié guāng dào xiǎo chuān zhū hù。",t:"槛菊愁烟兰泣露，罗幕轻寒，燕子双飞去。明月不谙离恨苦，斜光到晓穿朱户。",k:[["槛","栏杆"],["谙","了解、懂得"]],a:"这是晏殊的代表作。\"明月不谙离恨苦\"将明月拟人化，怨其不懂得离恨。全词写离愁别恨，风格风流蕴藉，是婉约词的名篇。"};
POEMS[112]={p:"hán chán qī qiè，duì cháng tíng wǎn，zhòu yǔ chū xiē。",t:"寒蝉凄切，对长亭晚，骤雨初歇。",k:[["凄切","凄凉急切"],["长亭","古代送别的亭子"]],a:"这是柳永的代表作。\"今宵酒醒何处？杨柳岸，晓风残月\"为千古名句，写酒醒后的凄清。全词以慢词写离愁，铺叙展衍，是婉约词的巅峰之作。"};
POEMS[113]={p:"dēng lín sòng mù，zhèng gù guó wǎn qiū，tiān qì chū sù。",t:"登临送目，正故国晚秋，天气初肃。",k:[["送目","远望"],["肃","肃杀、萧瑟"]],a:"这是王安石怀古词的代表作。全词以金陵为背景，抒发六朝兴亡之感。\"至今商女，时时犹唱，后庭遗曲\"讽刺不知亡国之恨。全词格调苍凉，笔力遒劲。"};
POEMS[114]={p:"lǎo fū liáo fā shào nián kuáng，zuǒ qiān huáng，yòu qíng cāng。\njǐn mào diāo qiú，qiān qí juǎn píng gāng。",t:"老夫聊发少年狂，左牵黄，右擎苍。锦帽貂裘，千骑卷平冈。",k:[["黄","黄犬"],["苍","苍鹰"],["卷平冈","席卷平坦的山冈"]],a:"这是苏轼知密州时所作，开豪放词风。\"会挽雕弓如满月，西北望，射天狼\"表达为国杀敌的壮志。全词气概豪迈，是苏轼豪放词的代表作。"};
POEMS[115]={p:"shí nián shēng sǐ liǎng máng máng，bù sī liáng，zì nán wàng。",t:"十年生死两茫茫，不思量，自难忘。",k:[["茫茫","遥远而模糊的样子"]],a:"这是苏轼悼念亡妻王弗的词。\"十年生死两茫茫\"写生死相隔的悲凉。\"相顾无言，惟有泪千行\"写梦中相见的凄惨。全词感情真挚深沉，是悼亡词的千古名篇。"};
POEMS[116]={p:"míng yuè jǐ shí yǒu？bǎ jiǔ wèn qīng tiān。\nbù zhī tiān shàng gōng què，jīn xī shì hé nián。",t:"明月几时有？把酒问青天。不知天上宫阙，今夕是何年。",k:[["几时有","什么时候有"],["宫阙","宫殿"]],a:"这是苏轼中秋赏月时所作。\"但愿人长久，千里共婵娟\"为千古名句，表达了对亲人的美好祝愿。全词由问月起兴，将人生哲理与月宫想象融为一体，是中秋词的绝唱。"};
POEMS[117]={p:"dà jiāng dōng qù，làng táo jìn，qiān gǔ fēng liú rén wù。",t:"大江东去，浪淘尽，千古风流人物。",k:[["大江","长江"],["风流人物","杰出的英雄人物"]],a:"这是苏轼贬黄州游赤壁时所作，豪放词的巅峰。\"人生如梦，一尊还酹江月\"以旷达作结。全词将壮阔江山与历史人物融为一体，气势磅礴，是宋词豪放派的代表作。"};
POEMS[118]={p:"mò tīng chuān lín dǎ yè shēng，hé fáng yín xiào qiě xú xíng。\nzhú zhàng máng xié qīng shèng mǎ，shuí pà？yī suō yān yǔ rèn píng shēng。",t:"莫听穿林打叶声，何妨吟啸且徐行。竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。",k:[["吟啸","吟咏长啸"],["徐行","慢慢走"]],a:"这是苏轼贬黄州时所作。\"回首向来萧瑟处，归去，也无风雨也无晴\"表达超然物外的旷达。全词以遇雨不惧喻人生逆境中的从容，体现了苏轼的人生态度。"};
POEMS[119]={p:"yì wài duàn qiáo biān，jì mò kāi wú zhǔ。\nyǐ shì huáng hūn dú zì chóu，gèng zhù fēng hé yǔ。",t:"驿外断桥边，寂寞开无主。已是黄昏独自愁，更著风和雨。",k:[["驿","驿站"],["无主","没有主人、无人赏"]],a:"这是陆游咏梅词的代表作。\"零落成泥碾作尘，只有香如故\"以梅花自喻，表达即使粉身碎骨也要保持高洁品格的精神。全词托物言志，格调悲壮。"};
POEMS[120]={p:"wǒ zhù cháng jiāng tóu，jūn zhù cháng jiāng wěi。\nrì rì sī jūn bú jiàn jūn，gòng yǐn cháng jiāng shuǐ。",t:"我住长江头，君住长江尾。日日思君不见君，共饮长江水。",k:[["长江头","长江上游"],["长江尾","长江下游"]],a:"这是李之仪的代表作。以长江水起兴，\"日日思君不见君，共饮长江水\"写相思之情。\"只愿君心似我心，定不负相思意\"为结句。全词语言清新，感情真挚。"};
POEMS[121]={p:"zuì lǐ tiǎo dēng kàn jiàn，mèng huí chuī jiǎo lián yíng。\nbā bǎi lǐ fēn huí xià zhì，wǔ shí xián fān sài wài shēng。\nshā chǎng qiū diǎn bīng。",t:"醉里挑灯看剑，梦回吹角连营。八百里分麾下炙，五十弦翻塞外声。沙场秋点兵。",k:[["麾下","部下"],["五十弦","泛指乐器"],["点兵","检阅军队"]],a:"这是辛弃疾寄给陈亮的壮词。\"了却君王天下事，赢得生前身后名。可怜白发生！\"表达壮志未酬的悲愤。全词气势豪迈，是豪放词的代表作。"};
POEMS[122]={p:"qiān gǔ jiāng shān，yīng xióng wú mì，sūn zhòng móu chù。",t:"千古江山，英雄无觅，孙仲谋处。",k:[["无觅","无处寻觅"],["孙仲谋","孙权字仲谋"]],a:"这是辛弃疾登北固亭怀古所作。\"凭谁问：廉颇老矣，尚能饭否？\"以廉颇自喻，表达报国之志。全词用典丰富，格调悲壮，是辛词代表作。"};
POEMS[123]={p:"chǔ tiān qiān lǐ qīng qiū，shuǐ suí tiān qù qiū wú jì。",t:"楚天千里清秋，水随天去秋无际。",k:[["楚天","南方的天空"],["无际","无边无际"]],a:"这是辛弃疾登建康赏心亭时所作。\"把吴钩看了，栏杆拍遍，无人会，登临意\"写壮志难酬的悲愤。全词格调悲凉，是辛弃疾豪放词的代表作。"};
POEMS[124]={p:"hé chù wàng shén zhōu？mǎn yǎn fēng guāng běi gù lóu。",t:"何处望神州？满眼风光北固楼。",k:[["神州","指中原地区"]],a:"这是辛弃疾登北固亭所作。\"生子当如孙仲谋\"借曹操语赞孙权，暗讽南宋当权者。全词格调雄放，怀古伤今。"};
POEMS[125]={p:"dōng fēng yè fàng huā qiān shù，gèng chuī luò，xīng rú yǔ。",t:"东风夜放花千树，更吹落，星如雨。",k:[["花千树","喻灯火繁盛"],["星如雨","喻烟花纷落"]],a:"这是辛弃疾元夕词的代表作。\"众里寻他千百度，蓦然回首，那人却在，灯火阑珊处\"为千古名句，王国维评为人生第三境界。全词以元夕繁华反衬孤高品格。"};
POEMS[126]={p:"shào nián bù shí chóu zī wèi，ài shàng céng lóu。\nài shàng céng lóu，wèi fù xīn cí qiáng shuō chóu。",t:"少年不识愁滋味，爱上层楼。爱上层楼，为赋新词强说愁。",k:[["层楼","高楼"],["强说愁","勉强说愁"]],a:"这是辛弃疾贬带湖时所作。\"却道天凉好个秋\"以欲说还休写愁之深重。全词以少年与而今对比，写愁之递进，含蓄深婉。"};
POEMS[127]={p:"yī lún qiū yǐng zhuǎn jīn bō，fēi jìng yòu zhòng mó。",t:"一轮秋影转金波，飞镜又重磨。",k:[["金波","月光"],["飞镜","飞天的明镜，喻月"]],a:"这是辛弃疾中秋词。\"乘风好去，长空万里，直下看山河\"写乘风奔月的豪情。全词格调清奇，想象丰富。"};
POEMS[128]={p:"nù fà chōng guān，píng lán chù，xiāo xiāo yǔ xiē。",t:"怒发冲冠，凭栏处，潇潇雨歇。",k:[["怒发冲冠","愤怒得头发竖起"],["潇潇","风雨急骤声"]],a:"这是岳飞的代表作。\"莫等闲，白了少年头，空悲切\"劝勉珍惜时光。\"待从头，收拾旧山河，朝天阙\"表达收复河山的壮志。全词气势磅礴，慷慨悲壮。"};
POEMS[129]={p:"cháng jì xī tíng rì mù，chén zuì bù zhī guī lù。\nxìng jìn wǎn huí zhōu，wù rù ǒu huā shēn chù。",t:"常记溪亭日暮，沉醉不知归路。兴尽晚回舟，误入藕花深处。",k:[["溪亭","溪边亭子"],["沉醉","大醉"]],a:"这是李清照早年所作。\"争渡，争渡，惊起一滩鸥鹭\"写急于归舟的生动场景。全词格调轻快，充满生活情趣。"};
POEMS[130]={p:"zuó yè yǔ shū fēng zhòu，nóng shuì bù xiāo cán jiǔ。\nshì wèn juǎn lián rén，què dào hǎi táng yī jiù。\nzhī fǒu，zhī fǒu？yīng shì lǜ féi hóng shòu。",t:"昨夜雨疏风骤，浓睡不消残酒。试问卷帘人，却道海棠依旧。知否，知否？应是绿肥红瘦。",k:[["雨疏","雨点稀疏"],["卷帘人","卷窗帘的侍女"],["绿肥红瘦","叶茂花少"]],a:"这是李清照的代表作。\"知否，知否？应是绿肥红瘦\"为千古名句，以绿红喻叶花，肥瘦写茂凋。全词借对话写惜春之情，新颖巧妙。"};
POEMS[131]={p:"bó wù nóng yún chóu yǒng zhòu，ruì nǎo xiāo jīn shòu。\njiā jié yòu chóng yáng，yù zhěn shā chú，bàn yè liáng chū tòu。",t:"薄雾浓云愁永昼，瑞脑销金兽。佳节又重阳，玉枕纱厨，半夜凉初透。",k:[["瑞脑","香料名"],["金兽","兽形铜香炉"],["纱厨","纱帐"]],a:"这是李清照重阳思夫之作。\"莫道不销魂，帘卷西风，人比黄花瘦\"为千古名句，以花瘦喻人瘦。全词写相思之苦，婉约含蓄。"};
POEMS[132]={p:"hóng ǒu xiāng cán yù diàn qiū。qīng jiě luó shang，dú shàng lán zhōu。",t:"红藕香残玉簟秋。轻解罗裳，独上兰舟。",k:[["玉簟","竹席的美称"],["罗裳","丝绸裙"]],a:"这是李清照思夫之作。\"此情无计可消除，才下眉头，却上心头\"为千古名句，写相思之不可排遣。全词格调清丽，感情深挚。"};
POEMS[133]={p:"fēng zhù chén xiāng huā yǐ jìn，rì wǎn juàn shū tóu。\nwù shì rén fēi shì shì xiū，yù yǔ lèi xiān liú。",t:"风住尘香花已尽，日晚倦梳头。物是人非事事休，欲语泪先流。",k:[["物是人非","景物依旧人事已非"]],a:"这是李清照晚年所作。\"只恐双溪舴艋舟，载不动许多愁\"以舟轻愁重写愁之深沉。全词写国破家亡后的悲苦，格调凄婉。"};
POEMS[134]={p:"xún xún mì mì，lěng lěng qīng qīng，qī qī cǎn cǎn qī qī。",t:"寻寻觅觅，冷冷清清，凄凄惨惨戚戚。",k:[["戚戚","忧愁的样子"]],a:"这是李清照晚年代表作。开篇十四个叠字写愁，前无古人。\"这次第，怎一个愁字了得\"以愁不可言传作结。全词写国破家亡、晚年孤苦之愁，是婉约词的巅峰。"};
POEMS[135]={p:"xiān yún nòng qiǎo，fēi xīng chuán hèn，yín hàn tiáo tiáo àn dù。\njīn fēng yù lù yī xiāng féng，biàn shèng què rén jiān wú shù。",t:"纤云弄巧，飞星传恨，银汉迢迢暗度。金风玉露一相逢，便胜却人间无数。",k:[["金风","秋风"],["玉露","白露"]],a:"这是秦观咏七夕的词。\"两情若是久长时，又岂在朝朝暮暮\"为千古名句，升华了爱情的境界。全词格调清丽，意境优美。"};
POEMS[136]={p:"huái zuǒ míng dōu，zhú xī jiā chù，jiě ān shǎo zhù chū chéng。",t:"淮左名都，竹西佳处，解鞍少驻初程。",k:[["淮左","淮水以东"],["名都","扬州"]],a:"这是姜夔过扬州所作。\"二十四桥仍在，波心荡，冷月无声\"写战后扬州的萧条。全词格调清空，是南宋咏物怀古词的代表作。"};
POEMS[137]={p:"xiǎo shān chóng dié jīn míng miè，bìn yún yù dù xiāng sāi xuě。",t:"小山重叠金明灭，鬓云欲度香腮雪。",k:[["小山","屏风上的山景"],["金明灭","阳光照射金碧闪烁"]],a:"这是温庭筠的代表作，花间词的鼻祖。全词以浓笔重彩写女子晨起梳妆的慵懒娇美，词风秾丽，对后世闺怨词影响深远。"};
POEMS[138]={p:"běi guó fēng guāng，qiān lǐ bīng fēng，wàn lǐ xuě piāo。",t:"北国风光，千里冰封，万里雪飘。",k:[["冰封","冰冻覆盖"]],a:"这是毛泽东的代表作。\"俱往矣，数风流人物，还看今朝\"为千古名句，气概豪迈。全词以雪景起兴，评点历代帝王，抒发当代英雄的豪情壮志。格调磅礴，意境深远。"};
POEMS[139]={p:"fēng yǔ sòng chūn guī，fēi xuě yíng chūn dào。\nyǐ shì xuán yá bǎi zhàng bīng，yóu yǒu huā zhī qiào。",t:"风雨送春归，飞雪迎春到。已是悬崖百丈冰，犹有花枝俏。",k:[["俏","俏丽、美丽"]],a:"这是毛泽东咏梅词。\"待到山花烂漫时，她在丛中笑\"写梅花不争春的品格。全词格调昂扬，以梅言志。"};
POEMS[140]={p:"chì chéng huáng lǜ qīng lán zǐ，shuí chí cǎi liàn dāng kōng wǔ？\nyǔ hòu fù xié yáng，guān shān zhèn zhèn cāng。",t:"赤橙黄绿青蓝紫，谁持彩练当空舞？雨后复斜阳，关山阵阵苍。",k:[["彩练","彩色的绸带，喻彩虹"]],a:"这是毛泽东忆大柏地之战的词。以彩虹起兴，\"装点此关山，今朝更好看\"写战后山色的美丽。全词格调明快。"};
POEMS[141]={p:"xiǎo zhù jīng huá，zǎo yòu shì zhōng qiū jiā jié。",t:"小住京华，早又是中秋佳节。",k:[["小住","暂住"],["京华","北京"]],a:"这是秋瑾的代表作。\"身不得，男儿列；心却比，男儿烈\"表达巾帼不让须眉的豪情。全词格调激昂，抒发革命情怀。"};
POEMS[142]={p:"shēn xiàng yú guān nà pàn xíng，yè shēn qiān zhàng dēng。\nfēng yī gèng，xuě yī gèng，guō suì xiāng xīn mèng bù chéng，gù yuán wú cǐ shēng。",t:"身向榆关那畔行，夜深千帐灯。风一更，雪一更，聒碎乡心梦不成，故园无此声。",k:[["榆关","山海关"],["聒","聒噪、吵扰"]],a:"这是纳兰性德随驾出关时所作。\"故园无此声\"写思乡之苦。全词以风雪声写乡愁，格调凄婉，是清词的代表作。"};
POEMS[143]={p:"jīn líng chéng shàng xī lóu，yǐ qīng qiū。\nwàn lǐ xī yáng chuí dì dà jiāng liú。",t:"金陵城上西楼，倚清秋。万里夕阳垂地大江流。",k:[["垂地","垂落地面"]],a:"这是朱敦儒南渡后所作。\"试倩悲风吹泪过扬州\"写国破之痛。全词格调悲凉，抒发故国之思。"};

const poems=JSON.parse(fs.readFileSync(path.join(DATA_DIR,'all_poems.json'),'utf8'));
let updated=0;
for(const poem of poems){
  if(!poem.id.startsWith('school_')) continue;
  const idx=parseInt(poem.id.replace('school_',''));
  const data=POEMS[idx];
  if(data){
    poem.pinyin=data.p;
    poem.translation=data.t;
    poem.keywords=data.k;
    poem.analysis=data.a;
    poem.authorIntro=AUTHORS[poem.author]||'';
    updated++;
  }
  if(!poem.authorIntro) poem.authorIntro=AUTHORS[poem.author]||'';
}
fs.writeFileSync(path.join(DATA_DIR,'all_poems.json'),JSON.stringify(poems));
console.log(`完成! 已为${updated}首中小学诗词添加赏析内容`);
const withPinyin=poems.filter(p=>p.pinyin).length;
const withTrans=poems.filter(p=>p.translation).length;
const withAnalysis=poems.filter(p=>p.analysis).length;
const withAuthor=poems.filter(p=>p.authorIntro).length;
console.log(`拼音:${withPinyin}, 译文:${withTrans}, 赏析:${withAnalysis}, 作者介绍:${withAuthor}`);
